window.BATCH_NOTES={"生物1":{"1.1":{"goals":["用极性与氢键解释水的性质和生命作用","用对照实验区分含水量、蒸发与温度变化"],"prerequisites":["分子内共价键与分子间作用力","比例、质量与温度单位"],"flow":["极性水分子","分子间氢键","热学与溶解性质","生命中的作用"],"deep":["水的O—H键是分子内共价键，氢键是水分子之间及与其他合适基团之间的相互作用。加热液态水主要改变分子运动与相互作用，不是把水大量拆成H₂与O₂。","高比热容使同样吸热时升温较小，高汽化热则使少量蒸发可带走较多能量；前者关乎温度变化，后者关乎相变，解释体温调节时不能混成同一过程。","极性水可稳定包围离子和某些极性分子，但“万能溶剂”过度概括。非极性油滴聚集说明水对不同物质的相互作用不同。自由水和结合水是组织水状态的简化描述，与抗逆性相关但不构成所有物种通用的单一因果定律。"],"derive":["热量模型Q＝mcΔT，在无相变、近似定比热条件下，c越大同样Q产生的ΔT越小；蒸发用Q＝mL，不能继续套升温公式。","比较叶片含水量：称鲜重，温和干燥至恒重再称干重，水比例＝(鲜−干)/鲜。干燥中挥发物与样品损伤可能影响结果，重复与同类样品对照必要。"],"exam":["解释用“分子结构—性质—功能”三段因果链；例如氢键—较高汽化热—蒸发散热。","数据题写清分母是鲜重还是干重；不同组织不能随意比较一个固定含水百分比。"],"examples":[{"q":"叶片鲜重10.0g，干至恒重2.0g，按鲜重算含水量。","steps":["估计失水质量10.0−2.0＝8.0g。","以鲜重为分母，8.0/10.0×100%＝80%。","若以干重为分母会得400%，那是不同指标，不是鲜重含水率。"],"ans":"80%。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"等质量水与某油液在相同受热条件下，水升温2℃、油升温4℃，能否据此比较比热？","steps":["若吸收热量确实相同且无相变，Q＝mcΔT。","c水/c油＝ΔT油/ΔT水＝4/2＝2。","实验上还须控制容器、热损与实际吸热，不能仅因使用同一热源就无条件断言Q相同。"],"ans":"在给定假设下水比热为油的2倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"为什么出汗但汗不蒸发时散热效果较弱？","steps":["排出汗液与蒸发是两个过程。","蒸发需吸收汽化潜热，把热量带离皮肤；高湿度使蒸发受限。","应归因于相变吸热而非仅“水温低”；不讨论具体医疗处理。"],"ans":"蒸发受限，汽化带走的热量减少。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"practice":[{"q":"基础：水分子内O—H键与分子间氢键相同吗？","steps":["O—H为连接原子的共价键。","氢键为分子间相互作用，强度与角色不同。"],"ans":"不同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"理解：冰浮在水面如何帮助水域生物？","steps":["冰密度较小先覆在水面。","表面冰层可减缓下层散热，使下方仍有液态水；不能说整个水体永不结冰。"],"ans":"表面结冰并减缓下层散热。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"应用：两同质量液体吸相同热、无相变，水温升较小，说明什么？","steps":["ΔT＝Q/(mc)，Q、m相同。","温升较小对应比热较大；需排除热损和相变差异。"],"ans":"水的比热较大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"综合2.2：水能溶解NaCl，是否Na⁺可自由穿过磷脂双层？","steps":["溶解性只描述水相中的相互作用。","膜内部疏水，带电离子仍需通道或载体；不能由溶于水推为可自由透膜。"],"ans":"不能，通常需膜运输蛋白。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":["2.2"]}],"quick":["水极性与氢键决定多项性质","比热与汽化热不同；含水率先看分母"],"quiz":{"q":"检测：水沸腾时为何不能说氢氧共价键全部断开？","steps":["汽化是相变，水分子仍为H₂O。","主要克服分子间作用而不是电解水；答混说明需重读两种键。"],"ans":"水分子仍存在，变化主要在分子间。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":1,"section_id":"1.1","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio01","url":"https://openstax.org/books/biology-2e/pages/3-introduction","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"1.2":{"goals":["把无机离子的作用联系到结构、渗透与缓冲","设计单一缺素对照并限制结论范围"],"prerequisites":["离子与化合物","对照变量、浓度与溶液"],"flow":["离子或盐形式","结构组分／调节作用","缺素实验","证据与限制"],"deep":["无机盐可以以溶解离子或不溶沉积形式存在；是否含碳不能用来一刀切判定有机物，碳酸盐、碳酸氢盐就是含碳的无机盐。盐不作为糖脂那样的代谢供能物，但可参与能量转化所需结构和过程。","Mg是叶绿素中心成分，Fe参与血红素等；Na⁺、K⁺梯度影响膜电活动和运输。生物效应取决于浓度、位置和调节，不能由“必需”推成“越多越好”。","缺素实验要用完整培养液对照与只缺一种元素的处理，控制植物品种、苗龄、光、温、液量和pH。处理症状可支持该元素必需，但仅凭黄叶不能唯一诊断缺Mg，因为病原、缺其他元素或光照也可能致黄。"],"derive":["缓冲体系能在一定范围内消耗外加H⁺或OH⁻，减缓pH变化，不表示pH绝对不变或可无限加酸碱。","设计缺Mg处理时要补偿伴随阴阳离子，尽量保持其他成分一致。恢复供应后能否缓解是补充证据，不能只比较不同年龄植株。"],"exam":["生物解释写具体元素、参与结构或机制、功能后果，避免只背“维持生命”。","实验评价分别指自变量、因变量和控制量，并说明证据不能排除什么。"],"examples":[{"q":"完整培养液植物绿，缺Mg组新观察到黄叶，能否直接断言所有黄叶均由缺Mg？","steps":["该对照若只改变Mg，支持Mg供应与本实验黄化相关。","叶绿素含Mg，为机制解释提供依据。","但其他原因也能黄化，不能推广为所有黄叶的唯一原因；需恢复供应等复核。"],"ans":"不能；只支持本条件下缺Mg影响。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"缺Mg处理、完整营养、缺Mg后补回Mg三组平均干重为3g、6g、5g，如何解读？","steps":["缺Mg组较完整组低，补回组有所恢复，描述上支持Mg供应与生长相关。","若其他条件一致，补回提供比仅两组比较更强的因果线索。","还需重复数、变异范围和统计分析，不能凭三个均值声称差异已显著或作用唯一。"],"ans":"支持Mg效应的线索；不能直接宣称统计显著。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"某学生说“碳酸氢盐含碳，所以是供能有机物”，指出两处问题。","steps":["含碳不等于有机物，碳酸氢盐属于无机盐。","无机盐可参与酸碱缓冲等，不按糖脂那样氧化供能。","分类和功能均需具体结构与机制证据。"],"ans":"分类标准错误，供能推断也错误。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"practice":[{"q":"基础：叶绿素中心相关的无机元素是什么？","steps":["叶绿素结构含Mg。","缺Mg可限制叶绿素形成，但黄化并非唯一诊断指标。"],"ans":"Mg。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"理解：缓冲液是否能让pH永远不变？","steps":["缓冲能力有限。","超过酸碱消耗容量后pH可明显改变，不能绝对化。"],"ans":"不能。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"应用：研究缺氮对植物生长，自变量与因变量可怎样选？","steps":["自变量为是否缺氮，其他营养尽量一致。","因变量可用相同时间后的干重增量，控制品种、光温和苗龄。"],"ans":"氮供应；干重增量等。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"综合1.1：为何比较植物处理后干重常比鲜重更能反映生长物质量？","steps":["鲜重含大量随水状态波动的水。","干重减少水分差异的影响，更接近累积干物质；仍需标准化干燥与取样。"],"ans":"减少含水状态造成的混淆。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":["1.1"]}],"quick":["无机盐可含碳；必需不等于越多越好","缺素实验只改变目标元素并设完整对照"],"quiz":{"q":"检测：两组植物品种、光照和营养都不同，能由长势差判定缺Mg效应吗？","steps":["多个变量同时改变，无法排除混淆。","需同品种同环境，只改变Mg供应；答不全回读控制变量。"],"ans":"不能，必须控制其他变量。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":1,"section_id":"1.2","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio01","url":"https://openstax.org/books/biology-2e/pages/3-introduction","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"1.3":{"goals":["联系糖苷键、单体与多糖功能","解释缩合、水解与还原糖检验的证据"],"prerequisites":["1.1水参与反应","单体、聚合物、化学键"],"flow":["单糖","缩合成糖苷键","多糖结构差异","贮能或支持功能"],"deep":["糖类并非全有甜味或全能直接通过膜。淀粉、糖原与纤维素都由葡萄糖相关单元构成，但连接方式与分支不同，使酶识别和功能不同；单体相同不代表聚合物性质相同。","缩合成一个连接通常失去一分子水，水解则消耗水断开相应连接。n个单体成一条无环链有n−1个连接，这个计数要注明链数、是否环状及模型，不能无条件套到所有复杂糖。","淀粉和糖原适合贮存，聚合减少相同碳量对应的可溶粒子数，减小相对渗透影响；纤维素直链间相互作用形成支持网络。还原糖检验阳性反映样品含可还原试剂的基团，并非唯一证明是葡萄糖。"],"derive":["无环单链n个葡萄糖缩合：相对质量≈180n−18(n−1)＝162n＋18；该式含端基，不应简单把每个单体都减18。","班氏检验需加热，碘液检验淀粉不以加热为必要条件。设葡萄糖阳性、水阴性对照，等体积、同加热条件；试剂由教师指导，水浴代替直接强火。"],"exam":["结构功能题写出具体键型、分支或链间作用，再接功能。","试剂题表述“支持含还原糖”，不把阳性写成唯一物质鉴定。"],"examples":[{"q":"5个葡萄糖缩合成一条无环链，脱水数和近似Mr多少？葡萄糖180。","steps":["无环单链连接数5−1＝4，脱4H₂O。","Mr＝5×180−4×18＝900−72＝828。","若误减5个水会少算一个端基所保留的18。"],"ans":"4个水；Mr＝828。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"淀粉水解样品由碘液阳性转阴性、班氏检验由弱转强，能推出什么？","steps":["碘反应减弱支持长链淀粉减少。","还原糖反应增强支持产生更多可还原糖成分，与水解相符。","不能仅凭这些检验唯一断定最终全是葡萄糖，还需底物、酶及进一步鉴定证据。"],"ans":"支持淀粉被水解并生成更多还原糖，不能唯一鉴定终产物。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"样品班氏检验加热后阳性，可以唯一认定葡萄糖吗？","steps":["班氏试剂检测还原性。","麦芽糖、乳糖等还原糖也可阳性。","需其他鉴定区分种类；阳性与对照一致只支持存在还原性成分。"],"ans":"不能，支持含还原糖而非唯一葡萄糖。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"practice":[{"q":"基础：蔗糖水解形成什么？","steps":["蔗糖由葡萄糖和果糖缩合形成。","水解消耗水，恢复这两种单糖。"],"ans":"葡萄糖与果糖。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"理解：人体不能直接利用纤维素的主要原因？","steps":["其β连接需要相应水解酶。","人体缺乏自身纤维素酶，不能因单体是葡萄糖就直接分解全部纤维素。"],"ans":"缺相应纤维素酶。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"应用：10个单糖成两条无环链，共脱多少水？","steps":["每条链连接数为单体数减1。","总连接10−2＝8，脱水8个，需链均非环。"],"ans":"8个水。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"综合2.2：把许多葡萄糖聚成糖原，为什么相对减小渗透影响？","steps":["渗透效应与可溶粒子数有关，不只总质量。","聚合后独立粒子数减少，并且大聚合物溶解状态不同；不是完全无渗透影响。"],"ans":"减少同碳量的独立溶质粒子数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":["2.2"]}],"quick":["单体相同，键型与分支可不同","无环n单体、m链：连接与脱水n−m"],"quiz":{"q":"检测：碘液阳性就说明样品含蛋白质吗？","steps":["碘液常用于检验淀粉。","蛋白质常用双缩脲检验；若混淆回读试剂与证据层次。"],"ans":"不是，支持淀粉。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":1,"section_id":"1.3","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio01","url":"https://openstax.org/books/biology-2e/pages/3-introduction","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"1.4":{"goals":["比较三甘油酯、磷脂与固醇的结构功能","从两亲性解释膜双层并比较储能效率"],"prerequisites":["1.1亲水与疏水","缩合与酯键"],"flow":["脂质类型","非极性或两亲性结构","聚集形式","储能／膜／调节功能"],"deep":["脂质是按溶解性质等归成的一大类，不都由重复单体聚合而成。三甘油酯为甘油与三脂肪酸形成三个酯键；固醇有四环骨架，不能强行套成“甘油＋脂肪酸”的同一模板。","脂肪酸链含较多可氧化C—H，完全氧化单位质量释放能量通常高于糖类；这不说明脂肪是所有组织每时每刻的首选燃料。储能脂质疏水，少伴随水，有利紧凑储存。","常见甘油磷脂头部亲水、两尾疏水，在水中疏水部分避水聚集形成双层。双层内部疏水阻碍离子直接通过，蛋白质承担许多特异运输；能自组装不代表所有物质都能透膜。饱和度与熔点还受链长及双键几何等影响，不宜把所有动物脂肪与植物油绝对化。"],"derive":["以题给能量值39kJ/g脂肪、17kJ/g糖计算，相同能量E需质量E/q。能量值是给定比较模型，非所有样品固定常数。","若做脂质乳化检验，用乙醇提取后加水产生乳白浑浊作为证据；乙醇易燃，远离明火，设水空白与已知油样对照，不使用高风险有机溶剂。"],"exam":["图上把磷脂头朝水、尾朝双层内部，两侧水相都要画出。","比较题按结构、极性、功能逐项写，不能只写“脂质储能”。"],"examples":[{"q":"题给脂肪39kJ/g、糖17kJ/g，提供78kJ各需多少g？","steps":["脂肪质量78/39＝2.00g。","糖质量78/17≈4.59g。","同能量脂肪质量较小；单位kJ除kJ/g得g。"],"ans":"2.00g脂肪；4.59g糖。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"相同链长脂肪酸，加入顺式双键通常如何影响紧密排列与熔点？","steps":["顺式双键使链弯折，难以像全饱和直链那样紧密堆积。","分子间接触方式改变，通常降低熔点。","链长、双键数及反式结构也有影响，不能把所有不饱和脂质都说成常温液体。"],"ans":"通常排列较松、熔点较低，需限定比较条件。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"为何磷脂双层的两侧都朝向亲水头？","steps":["膜两侧均接触水相，头部与水相互作用较有利。","疏水尾在内部聚集，减少与水接触。","若把外侧头向水、内侧尾向细胞质，则细胞质同样含水，与两亲性矛盾。"],"ans":"两侧均为水环境，疏水尾藏内。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]}],"practice":[{"q":"基础：一分子三甘油酯含几条脂肪酸链？","steps":["甘油的三个羟基分别形成酯键。","典型三甘油酯含3条脂肪酸链。"],"ans":"3条。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"理解：固醇也是甘油加三脂肪酸吗？","steps":["固醇有四个相连环的基本骨架。","三甘油酯结构不适用于所有脂质。"],"ans":"不是。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"应用：按模型合成2个三甘油酯形成多少酯键、脱多少水？","steps":["每个三甘油酯形成3个酯键、脱3水。","两分子共6个酯键、6个水。"],"ans":"各6。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"综合2.2：磷脂双层存在是否足以让Na⁺快速自由通过？","steps":["内部疏水对带电Na⁺有能量屏障。","通常需要离子通道或转运蛋白，磷脂头亲水不能消除内部屏障。"],"ans":"不足，通常需运输蛋白。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":["2.2"]}],"quick":["三甘油酯储能、磷脂两亲成膜、固醇四环","不能把所有脂质当同一聚合物"],"quiz":{"q":"检测：膜内疏水尾向外接触细胞液的图哪里错？","steps":["细胞液含水，尾暴露不符合稳定双层排列。","头应朝两侧水相，尾相对藏内；回读两亲性。"],"ans":"尾应向内，头朝水。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.4","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":1,"section_id":"1.4","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio01","url":"https://openstax.org/books/biology-2e/pages/3-introduction","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"1.5":{"goals":["按结构层次联系蛋白质功能与变性","计算无环多肽的肽键、脱水和质量"],"prerequisites":["氨基酸通式与缩合","1.1氢键与共价键"],"flow":["氨基酸序列","局部结构","整体折叠／亚基","形状与功能","变性或水解"],"deep":["肽键将氨基酸主链连为序列，R基差异影响折叠与相互作用。二级结构主要由主链间氢键稳定，三级涉及多种R基作用，四级为多个亚基装配；不是每个蛋白质都有四级。","通常变性破坏空间构象而不等于把肽链水解为氨基酸。加热导致活性下降可由活性位形状改变解释；强烈长期处理可能同时水解，不能把“任何条件下一级结构必不变”写成绝对命题。","n个氨基酸形成m条非环状、未额外交联的肽链，主链肽键和缩合水数为n−m。游离端基至少每链各一，但若R基也带氨基或羧基，总数可更多。"],"derive":["相对质量＝各氨基酸相对质量和−18(n−m)。二硫键形成等额外化学变化若题目另给，须另计，不能隐藏在简单脱水式中。","双缩脲显色与多个肽键有关，设置蛋白阳性与水阴性对照；游离氨基酸不能仅因含N就判为同样阳性。试剂含碱与铜盐，按教师规范操作。"],"exam":["结构功能题给“作用力改变—空间形状改变—结合或催化改变”的链条。","计数先注明链数、环状与侧链条件，再套n−m。"],"examples":[{"q":"共100个氨基酸形成2条无环肽链，平均Mr各110，求肽键、水和产物近似Mr。","steps":["肽键＝100−2＝98，缩合水98个。","单体总相对质量100×110＝11000。","产物总Mr＝11000−98×18＝9236；无其他反应时成立。"],"ans":"98个肽键、98个水，Mr总和9236。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"由6个氨基酸形成2条无环肽链，各单体Mr＝100，求总肽键与总产物Mr。","steps":["肽键与脱水数＝n−m＝6−2＝4。","单体总Mr＝600，脱4个水扣72，产物Mr总和528。","不同链长分配不改变总连接数，假设没有额外交联或其他反应。"],"ans":"4个肽键；Mr总和528。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"酶加热失活但检测主链仍完整，解释发生了什么。","steps":["加热可改变维持构象的非共价作用。","活性位空间形状改变，结合或催化能力下降。","主链仍完整符合变性，而不是必须发生肽键水解。"],"ans":"构象变性使功能下降。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]}],"practice":[{"q":"基础：形成肽键的是哪两类基团？","steps":["一个氨基酸羧基与另一个氨基酸氨基缩合。","脱水后形成—CO—NH—连接。"],"ans":"羧基与氨基。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"理解：所有蛋白质都有四级结构吗？","steps":["四级要求多个多肽亚基组装。","单条肽链蛋白可只有一、二、三级结构。"],"ans":"不是。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"应用：8个氨基酸成一条无环肽链，脱水多少？","steps":["连接数8−1＝7。","每连接脱一水，因此7个水。"],"ans":"7个。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"综合3.1：氨基酸序列变动为什么可能改变酶活性？","steps":["序列决定R基分布与折叠约束。","构象或活性位变化会影响底物结合和反应；并非每个替换都会使活性完全丧失。"],"ans":"可能通过折叠和活性位改变影响催化。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":["3.1"]}],"quick":["主链肽键与空间构象分开","无环n单体、m链：肽键n−m"],"quiz":{"q":"检测：蛋白质变性与水解可当同义词吗？","steps":["变性主要改变空间构象。","水解断肽键使链变短或成氨基酸，两者层次不同；回读结构层次。"],"ans":"不能。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.5","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":1,"section_id":"1.5","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio01","url":"https://openstax.org/books/biology-2e/pages/3-introduction","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"1.6":{"goals":["区分DNA、RNA组成及链连接","在双链条件下完成碱基与氢键计数"],"prerequisites":["1.3单体与聚合物","比例、互补配对"],"flow":["核苷酸组成","糖磷酸骨架","碱基序列","互补双链","遗传信息"],"deep":["核苷酸由磷酸、五碳糖、碱基组成。DNA用脱氧核糖和A、T、G、C，RNA用核糖和A、U、G、C；A、G可同时存在两类核酸，不能只凭一个腺嘌呤判断是哪类。","同链核苷酸由共价磷酸二酯连接，双链之间碱基用氢键配对。这两类键的作用位置不同；DNA解链通常先分开互补链，不等于骨架被水解。","双链DNA总体A＝T、G＝C来自配对，不能直接套到单链RNA或DNA某一条链。DNA常为双链、RNA常为单链是教材典型，不表示没有例外；细胞核、线粒体和叶绿体均可能含DNA，RNA也可在核内形成。"],"derive":["设双链DNA共N个核苷酸、G比例g，则G＝C＝gN，A＝T＝(1−2g)N/2。碱基对数为N/2，而不是N。","若AT对数a、GC对数b，则氢键数2a＋3b。该计数指理想完整互补双链，不包含其他稳定作用。"],"exam":["碱基题先圈总链还是单链、核苷酸数还是碱基对数。","说明信息以碱基序列承载，不是只由A/T/G/C总比例决定。"],"examples":[{"q":"双链DNA共1000个核苷酸，A占20%，求各碱基数与对数。","steps":["A＝200，按配对T＝200。","剩余600为G＋C，各300。","总碱基对1000/2＝500；AT对200、GC对300。"],"ans":"A、T各200；G、C各300；500对。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"DNA一条链为5′-AGTC-3′，写出反向平行互补链。","steps":["按A—T、G—C、T—A、C—G配对得TCAG。","对应方向为3′-TCAG-5′；若统一按5′→3′写则为5′-GACT-3′。","只替换碱基而不处理方向会写成错误的同向平行结构。"],"ans":"3′-TCAG-5′，或按另一读向5′-GACT-3′。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"上题理想双链氢键数多少？","steps":["AT对为200，每对2个氢键，贡献400。","GC对为300，每对3个，贡献900。","总1300；若把G与C都算成300对会重复。"],"ans":"1300个。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]}],"practice":[{"q":"基础：RNA中的糖和DNA不同在哪里？","steps":["RNA为核糖，DNA为脱氧核糖。","二者均五碳糖，但化学基团不同，不能只说一个有糖一个无糖。"],"ans":"核糖／脱氧核糖。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"理解：单链RNA中A一定等于U吗？","steps":["没有完整互补双链作为全链配对限制。","局部可配对，但总体比例不必A＝U。"],"ans":"不一定。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"应用：双链DNA中G占30%，A占多少？","steps":["C也30%，G＋C共60%。","A＋T为40%，A与T各20%。"],"ans":"20%。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"综合1.3：同链核苷酸连接与两链碱基配对分别是什么键？","steps":["同链糖磷酸骨架为共价磷酸二酯键。","两链互补碱基主要通过氢键配对；解链不必断骨架。"],"ans":"磷酸二酯键；氢键。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":["1.3"]}],"quick":["先分DNA/RNA，再分单链/双链","总核苷酸数＝2×碱基对数"],"quiz":{"q":"检测：两个DNA的碱基百分比相同，遗传信息一定相同吗？","steps":["总比例相同不规定排列顺序。","不同序列可有相同组成，信息需看序列；回读碱基序列层次。"],"ans":"不一定，序列可不同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":1,"primary_section":"1.6","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":1,"section_id":"1.6","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio01","url":"https://openstax.org/books/biology-2e/pages/3-introduction","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]}},"生物2":{"2.1":{"goals":["区分原核、真核及动植物典型细胞","换算显微图长度并解释表面积体积比"],"prerequisites":["1.5蛋白质、1.6核酸","长度单位与立方体面积体积"],"flow":["细胞学说","显微证据","原核与真核","特化例外","大小与交换限制"],"deep":["细胞学说描述细胞生命的共同组织层次；病毒无细胞结构，需宿主完成增殖，不能把“有遗传物质”直接当成完整细胞。原核有DNA、核糖体和细胞膜，缺少核膜包被的细胞核，不能说没有遗传物质或不能合成蛋白质。","动植物比较应说典型结构：绿色光合细胞有叶绿体，根细胞通常没有；成熟哺乳类红细胞丢失细胞核和许多细胞器，但仍源自真核细胞谱系。用一条绝对化形态规则分类容易误判。","显微镜放大倍数与分辨率不同：把模糊图放更大不等于出现更多细节。图像经过印刷缩放时，比例尺比标称放大倍数更稳健，因为标尺与图一起缩放。","细胞增大使体积按边长三次、表面积按二次增长，单位体积可用交换面积减少，扩散距离也增长；这支持细胞尺度受限，但不说明所有细胞都必须同样小，形状、膜褶皱和运输也会改变约束。"],"derive":["立方体边长a，表面积6a²、体积a³，SA/V＝6/a，单位为长度⁻¹。边长扩大2倍，SA/V减半。","实际长度＝图像长度/放大倍数；先统一单位。若用标尺，实际长度＝目标图长/标尺图长×标尺实际长度。"],"exam":["分类题结合多项结构证据，不能只看有没有细胞壁。","计算题先统一mm、µm，放大倍数无单位；图像长度不能当成实际细胞大小。"],"examples":[{"q":"显微照片细胞长36mm、放大1200倍，实际长度？","steps":["36mm＝36000µm。","实际长度36000/1200＝30µm。","若直接36/1200再写µm会错1000倍；0.030mm也等于30µm。"],"ans":"30µm。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"显微镜物镜40×、目镜10×，总放大倍数多少；换更高倍目镜是否必增加可分辨细节？","steps":["总放大40×10＝400倍。","可分辨细节受光学分辨率限制，更高目镜可能只把已有模糊图放大。","需要区别放大与分辨，不能只用乘积大来证明分辨率提高。"],"ans":"400倍；不保证。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"立方细胞边长由1单位增至2单位，表面积、体积与比值如何变？","steps":["原SA＝6、V＝1，比值6。","新SA＝24、V＝8，比值3。","面积4倍、体积8倍，所以比值减半；比值数值需配相应长度单位。"],"ans":"面积4倍、体积8倍，SA/V减半。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"practice":[{"q":"基础：细菌没有核膜，是否没有DNA？","steps":["细菌DNA主要位于拟核，也可有质粒。","无核膜不等于无遗传物质。"],"ans":"有DNA。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"理解：根细胞没有叶绿体，能否据此判为动物细胞？","steps":["根细胞属植物，通常不光合。","还需看细胞壁、液泡及其他证据，不能只用叶绿体单项。"],"ans":"不能。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"应用：图中20mm标尺代表10µm，目标长60mm，实际长度？","steps":["目标与标尺图长比60/20＝3。","实际长度3×10＝30µm，比例尺与图同倍率。"],"ans":"30µm。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"综合2.2：细胞体积变大但表面积相对不足，会怎样影响交换？","steps":["单位体积的交换表面积下降，扩散路程增加。","若需求随体积增大，简单扩散可能不足，需要形状、膜褶皱或运输等适应。"],"ans":"相对交换能力下降，需相应适应。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":["2.2"]}],"quick":["原核无核膜但有DNA和核糖体","放大不等于分辨；SA/V＝6/a"],"quiz":{"q":"检测：成熟红细胞无细胞核，能归为细菌吗？","steps":["它是哺乳动物真核细胞分化形成的特化细胞。","不能只凭核有无判谱系，需结合来源、结构和功能；回读特化例外。"],"ans":"不能，特化真核细胞。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":2,"section_id":"2.1","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio02","url":"https://openstax.org/books/biology-2e/pages/4-introduction-to-cell-structure","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"2.2":{"goals":["用流动镶嵌模型解释选择透过性","按梯度、蛋白与能量区分运输并设计渗透实验"],"prerequisites":["1.4磷脂两亲性","浓度梯度与对照实验"],"flow":["两亲磷脂双层","疏水屏障与膜蛋白","被动／主动运输","渗透和体积变化"],"deep":["流动描述膜组分可侧向运动，镶嵌描述蛋白分布于脂双层中。膜糖链朝细胞外侧，与细胞识别相关，不应在双层两侧随机镜像。脂双层不是筛孔大小唯一决定通透性的薄网，电荷与脂溶性也关键。","简单扩散和易化扩散均顺相关梯度、不直接耗代谢能；后者依靠蛋白，载体可饱和。离子一般需考虑电化学梯度而非只有浓度差。主动运输需能量，既可直接利用ATP，也可利用其他离子梯度间接耦联。","水的净渗透方向更一般由水势差决定。同压、溶质不易透膜的简单情境中水从稀到浓；两侧分子都在双向运动，平衡是净移动为零而非分子停止。植物细胞壁限制膨胀，动物细胞无壁可能在足够低渗环境中涨破。","质壁分离需活细胞膜保持选择透过性；过强或过久高渗处理可损伤细胞，复原不是任何条件下都保证。小肠葡萄糖摄取可借Na⁺梯度，不能把所有耗能运输都说成载体直接水解ATP。"],"derive":["马铃薯渗透实验质量变化率＝(末质量−初质量)/初质量×100%。控制条块尺寸、来源、温度、浸泡时间、溶液体积，称量前以同法轻吸表面液体。","将质量变化率对外液浓度作图，接近零点可估计该实验条件的等净交换点；不是在所有压力与温度下通用的细胞浓度常数。"],"exam":["题型判断先问所运对象、梯度方向、是否依蛋白、能源来源。","曲线平台不能单独证明主动运输；载体介导的被动运输也可能饱和。"],"examples":[{"q":"马铃薯条初重2.00g、浸泡后2.20g，质量变化率和水净移动方向？","steps":["变化2.20−2.00＝0.20g。","变化率0.20/2.00×100%＝10.0%。","在溶质贡献可忽略且表面水已处理的模型下，支持净吸水；不能仅凭增重就精确给水势数值。"],"ans":"＋10.0%；支持水净进入。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"同来源、相同初始状态与大小的马铃薯条置三种浓度液中，质量变化依次＋12%、0%、−8%，怎样排序外液相对水势？","steps":["在相同压力与可比条件下，净吸水组外液水势相对较高，净失水组相对较低。","零变化组接近净水交换平衡，可作为两者间参照。","排序为＋12%组较高、0%组居中、−8%组较低；不能由百分比直接给绝对水势数值。"],"ans":"外液水势由高到低：＋12%、0%、−8%组（给定条件下）。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"一种物质顺梯度经载体进入细胞，速率有平台，是否一定主动运输？","steps":["顺梯度且无能量耦联符合易化扩散。","平台可由载体数量或转运速率有限造成。","主动运输需有逆相关梯度或能量耦联证据，单凭饱和不能认定。"],"ans":"不一定，可为易化扩散。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"practice":[{"q":"基础：O₂通常通过脂双层进入细胞属于什么？","steps":["O₂为小的非极性分子，可直接穿过脂双层。","沿分压相关梯度净扩散，不需载体直接耗ATP。"],"ans":"简单扩散。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"理解：渗透平衡时水分子停止运动吗？","steps":["水仍双向移动。","平衡表示两个方向通量相等、净通量为0。"],"ans":"不停止。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"应用：样条由2.50g变2.25g，变化率？","steps":["差值−0.25g。","−0.25/2.50×100%＝−10%，支持净失水。"],"ans":"−10%。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"综合1.4：Na⁺难直接过膜但可经通道流入，说明双层和蛋白各自作用？","steps":["双层内部疏水限制带电离子。","特定通道提供选择性通路；顺电化学梯度流动可为被动，不能见离子就答主动。"],"ans":"脂双层屏障、通道选择性通路。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":["1.4"]}],"quick":["被动顺梯度，主动需能量耦联","渗透看净水移动；饱和不等于主动"],"quiz":{"q":"检测：Na⁺–葡萄糖协同运输是否必由协同载体本身直接水解ATP？","steps":["协同运输可利用Na⁺梯度驱动葡萄糖。","该梯度由ATP驱动泵维持，属于间接依赖；回读一级与二级主动机制。"],"ans":"不必；可间接利用ATP建立的梯度。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":1,"question_no":1,"source":"https://duzhongacademy.com/pastpapers/uec-2025/biology/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"生物","subject_code":"biology","chapter_id":2,"section_id":"2.2","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio02","url":"https://openstax.org/books/biology-2e/pages/4-introduction-to-cell-structure","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"2.3":{"goals":["将细胞器结构与特定功能联系","根据时序标记推断分泌运输路径并限制结论"],"prerequisites":["1.5蛋白质与1.6核酸","2.2膜泡及膜流动性"],"flow":["核糖体合成","粗面内质网加工","囊泡","高尔基体","分泌囊泡","胞吐"],"deep":["细胞器膜把反应分区，既保持不同化学环境又提供表面积。线粒体内膜嵴增加呼吸相关膜面积，叶绿体类囊体承载光反应，基质参与碳同化；不能把所有代谢都塞入一个“工厂”。糖酵解在细胞质，能量需求也不能仅由线粒体数量单独决定。","核糖体合成多肽，粗面内质网和高尔基体参与许多分泌／膜蛋白的折叠加工与分选。高尔基体不是蛋白质初始翻译场所，线粒体不是输送分泌蛋白的串联站。","脉冲标记后追踪不同时间标记位置，先后峰值可支持运输次序。要控制标记持续时间和追踪条件，并区分“检测到标记”与“全部蛋白都经过这里”。细胞器也可能交换、回收膜，不能从单次胞吐推断膜面积永远增加。","游离与附着核糖体的差别在合成目标蛋白的定位过程，并非两类永久不同的机器；一些蛋白后续进入核、线粒体等，不是所有细胞内用蛋白都留在细胞质。"],"derive":["按膜层数分类：线粒体、叶绿体为双膜；内质网、高尔基体等为单膜囊；核糖体无膜。线粒体双膜不包含把嵴重复算成第三层外包膜。","教学可用无放射性图片时序资料做追踪推理；真实同位素实验不在家庭环境操作。因变量可为各区室标记比例随时间，自变量为追踪时间。"],"exam":["结构功能解释用“增加何处面积／维持何种区室—承载何种反应”表达。","时序题先找最早峰与后继峰，再论证路径，不只背箭头。"],"examples":[{"q":"标记氨基酸后，2min主要在粗面内质网、10min在高尔基体、20min在囊泡，支持什么路径？","steps":["氨基酸先被合成为多肽，最早出现在粗面内质网相关区。","随后高尔基体，再到囊泡，支持分泌加工运输序列。","还需终点细胞外标记等证据确认分泌，不能据此说所有蛋白都沿同一路径。"],"ans":"粗面内质网→高尔基体→囊泡，支持分泌路径。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"细胞呼吸旺盛但不能合成分泌蛋白，能否仅增加线粒体数量来恢复分泌？","steps":["分泌需要完整的翻译、加工、分选和囊泡运输系统。","ATP供应只是必要条件之一；若核糖体或内质网功能受损，仅供能增加不足。","结构与功能关系不能简化成“线粒体越多，一切活动越强”。"],"ans":"不能保证，需检查合成加工运输环节。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"胰腺分泌蛋白较旺盛的细胞为何常有发达粗面内质网和高尔基体？","steps":["粗面内质网上核糖体合成相关多肽并入内质网加工。","高尔基体进一步修饰、分选并包装运输。","结构数量增加与功能需求匹配，但不能只按数量推断具体分泌速率。"],"ans":"适应蛋白合成、加工和包装需求。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"practice":[{"q":"基础：蛋白质翻译的直接场所是什么？","steps":["读取mRNA并连接氨基酸的机器为核糖体。","高尔基体主要加工分选，不负责初始翻译。"],"ans":"核糖体。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"理解：线粒体应画在分泌蛋白依次经过的路线里吗？","steps":["它可为过程提供ATP，但不是该蛋白串联运输站。","可用旁支能源箭头表示，不能用粗面内质网→线粒体→高尔基体。"],"ans":"不应作串联站。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"应用：细胞器双膜、内膜折叠为嵴，最可能是什么？","steps":["双膜且有嵴是线粒体典型结构。","其内膜结构与呼吸相关膜过程相适应；叶绿体典型内部为类囊体。"],"ans":"线粒体。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"综合2.2：分泌囊泡如何把内容排到外面，是否需穿过脂双层疏水内部？","steps":["囊泡膜与细胞膜融合，内容经开放通路排出。","这是胞吐，依赖膜动态与能量，不是大分子逐个扩散穿过疏水层。"],"ans":"胞吐，通过膜融合。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":["2.2"]}],"quick":["核糖体合成，多种膜区室加工与分选","供能关系不等于货物运输路线"],"quiz":{"q":"检测：持续分泌是否必然使细胞膜无限增大？","steps":["胞吐可增加局部膜，但同时有胞吞回收、合成与再分配。","动态平衡需综合膜流量，回读膜回收。"],"ans":"不必，膜有回收与动态平衡。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":1,"question_no":2,"source":"https://duzhongacademy.com/pastpapers/uec-2025/biology/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"生物","subject_code":"biology","chapter_id":2,"section_id":"2.3","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio02","url":"https://openstax.org/books/biology-2e/pages/4-introduction-to-cell-structure","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"2.4":{"goals":["解释核膜、核孔、染色质与核仁功能","评价核移植或嫁接证据的范围"],"prerequisites":["1.6DNA信息与RNA","2.3蛋白质合成与区室"],"flow":["DNA与染色质","转录及核质交流","蛋白质表达","细胞功能"],"deep":["核控制不是一个“下命令”的拟人器官，而是遗传信息通过转录、RNA加工与后续蛋白表达影响细胞。细胞质环境、信号和已有蛋白也参与调控，不能把一切性状都只归核。","核膜双层分隔核质，核孔提供选择性大分子通行。蛋白可输入、RNA可输出，小分子也可扩散；“核孔只让RNA过”过窄，“任何大分子随便过”则过宽。完整核内DNA通常保留于核内，核分裂与核膜解体等情境需另论。","染色质和染色体描述同类DNA蛋白复合物不同凝缩状态，不是DNA变成完全不同化学物。核仁参与rRNA生成和核糖体亚基组装，不等于整个核糖体在核仁内完成细胞质翻译。","核移植、伞藻嫁接可支持核中信息对某些性状的重要作用，但需考虑残留细胞质物质和时间。短期形态受旧物质影响，不必否认长期核遗传控制。"],"derive":["示意链：核DNA→转录RNA→经核孔输出部分RNA→细胞质翻译／定位→功能。此为典型真核基因表达概览，RNA有不同去向。","证据设计比较去核、保核与核移植组，控制损伤和培养条件；只有去核与死亡的关联还不足排除手术损伤影响。"],"exam":["实验题分别写观察、推断与限制。","结构功能题把“选择性通道”与“遗传信息保留”说清，不把核孔画为无边界大洞。"],"examples":[{"q":"去核组很快失去功能，保核对照正常，能说明核什么作用？","steps":["在操作损伤等被控制时，结果支持核对持续细胞功能重要。","核含遗传信息，影响蛋白表达，可提供机制解释。","不能由短期观察说细胞质无作用，需更多对照排除操作损伤。"],"ans":"支持核的重要性，结论需受对照与范围限制。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"某处理阻止成熟mRNA输出但不立即破坏已有蛋白，细胞质蛋白合成是否会瞬间全部停止？","steps":["已有细胞质mRNA和蛋白可短期继续发挥作用。","新转录信息无法正常补充，随原有mRNA降解，相关新蛋白合成可能逐步受影响。","需时间序列与特异性对照，不能只凭一个时间点断言全部过程立即停。"],"ans":"不一定瞬间全部停，可能出现随时间发展的影响。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"核内形成mRNA而核糖体在细胞质，信息如何到达翻译场所？","steps":["典型真核mRNA经加工后通过核孔输出。","在细胞质与核糖体关联并被翻译。","DNA本身通常无需离核，转移的是RNA信息载体。"],"ans":"mRNA经核孔输出，DNA通常保留。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"practice":[{"q":"基础：染色质主要由什么组成？","steps":["主要为DNA与相关蛋白。","分裂时凝缩形成可见染色体，化学信息载体并未凭空改变。"],"ans":"DNA与蛋白质。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"理解：核仁是细胞全部蛋白质合成场所吗？","steps":["核仁参与rRNA及核糖体亚基形成。","翻译主要由核糖体完成，不能把组装核糖体等同于翻译所有蛋白。"],"ans":"不是。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"应用：示意图将核孔画成只可单向输出RNA，有何遗漏？","steps":["核孔具有选择性但有双向运输。","某些蛋白需要从细胞质输入核内，因此不能画成仅RNA单向阀。"],"ans":"遗漏蛋白输入等双向交通。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"综合1.6：核与线粒体都含DNA，能否说细胞全部遗传信息都在核？","steps":["多数真核遗传信息在核，线粒体等也有自身DNA。","因此“全部”不准确；须区分主要位置与唯一位置。"],"ans":"不能说全部。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":["1.6"]}],"quick":["核信息通过基因表达发挥作用","核孔选择性双向交通；染色质与染色体同类物质不同状态"],"quiz":{"q":"检测：移植后立即观察到旧性状，能否立即否定核的作用？","steps":["旧细胞质已有蛋白、RNA可暂时维持表现。","需时序、充分更新与对照再判断；回读证据滞后。"],"ans":"不能，需考虑残留与观察时间。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.4","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":2,"section_id":"2.4","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio02","url":"https://openstax.org/books/biology-2e/pages/4-introduction-to-cell-structure","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"2.5":{"goals":["区分植物细胞壁与细胞膜的结构功能","解释膨压、质壁分离及不同生物壁成分"],"prerequisites":["1.3纤维素","2.2渗透与选择透过性"],"flow":["纤维素网络与基质","壁的支持约束","膨压","膜与壁不同作用"],"deep":["植物细胞壁在膜外，纤维素微纤丝与其他多糖构成支持网络。初生壁适应生长，次生壁可在内侧增厚并木质化；并非所有植物细胞都具同样发达次生壁。胞间层富果胶，帮助邻接细胞粘合。","水进入后细胞内容积膨胀，细胞壁限制无限扩张并产生反作用，使膨压建立。保护作用来自机械约束，不代表壁阻止所有水进入。选择性跨膜控制主要由细胞膜与液泡膜等承担。","教材称壁“全透”是相对膜的简化：水与许多小溶质可过，不表示任意大小分子都无限制通过。细菌壁主要肽聚糖、真菌壁富几丁质等，不能把所有壁都叫纤维素。","胞间连丝穿过壁连接相邻细胞，提供受调控交流路径；细胞壁有通道不意味着细胞完全失去各自膜边界。"],"derive":["质壁分离中，外液使细胞净失水，原生质体收缩而相对刚性壁保形；分离的是原生质体边界与壁，不是壁从细胞外自行脱落。","观察需选有细胞壁和可见液泡／色素的活植物组织；正常液与高渗液作对照，并限制暴露时间，避免不可逆损伤。"],"exam":["图示标出壁在外、膜在内，失水后两者分离。","比较题以材料、位置、选择性、机械支持分别写，不用“有壁所以不渗透”。"],"examples":[{"q":"植物细胞在稀溶液中吸水为何通常不涨破？","steps":["水可跨膜进入，内容膨胀。","壁产生机械约束，使膨压增加并限制继续体积增大。","不是壁完全挡水；若壁被去除，保护条件改变。"],"ans":"细胞壁机械约束与膨压建立。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]},{"q":"比较植物与真菌细胞，均见细胞壁，能否用壁的存在唯一判断为植物？","steps":["两者都可有细胞壁，存在与否不是充分证据。","植物壁主要纤维素，真菌壁通常富几丁质等，应结合成分与其他结构。","还可比较叶绿体、营养方式等证据，但非绿色植物细胞也可无叶绿体，不能再用单项绝对规则。"],"ans":"不能，需要壁成分及其他证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]},{"q":"高渗液中质壁分离，壁为何没有一起明显缩小？","steps":["净失水主要使原生质体和液泡收缩。","壁较刚性且允许水、小溶质通过，形状变化较小。","两者分离显示膜内水状态与壁机械性质不同。"],"ans":"原生质体收缩，较刚性壁保形。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]}],"practice":[{"q":"基础：植物壁的主要结构多糖是什么？","steps":["典型植物细胞壁含纤维素微纤丝。","真菌与细菌壁成分不同，不套同一答案。"],"ans":"纤维素。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]},{"q":"理解：有壁的细胞是否就没有细胞膜？","steps":["壁位于膜外，是另一结构。","活植物、细菌等仍有细胞膜执行边界和运输功能。"],"ans":"仍有细胞膜。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]},{"q":"应用：细菌与真菌壁分别常以何种成分区别于植物？","steps":["典型细菌为肽聚糖。","真菌富几丁质等；植物主要为纤维素网络。"],"ans":"肽聚糖；几丁质等。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]},{"q":"综合2.2：动物细胞在高渗液失水能叫质壁分离吗？","steps":["动物细胞无细胞壁，失水可皱缩。","没有原生质体与细胞壁分开的结构条件，不能称质壁分离。"],"ans":"不能，称失水皱缩等。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":["2.2"]}],"quick":["壁主要支持，膜主选择透过","植物壁纤维素，不能套全部生物"],"quiz":{"q":"检测：“植物壁全透，所以任何蛋白都可无限制通过”对吗？","steps":["教材全透是相对许多小溶质而言。","壁网络有孔径和基质作用，并非对任意大分子无条件开放；回读简化边界。"],"ans":"不对，不能无限推广。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":2,"primary_section":"2.5","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"生物","subject_code":"biology","chapter_id":2,"section_id":"2.5","content_sources":[{"source_id":"dz_biology","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_bio02","url":"https://openstax.org/books/biology-2e/pages/4-introduction-to-cell-structure","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]}},"化学3":{"3.1":{"goals":["用粒子观点解释化学反应前后元素不变而物质改变","比较道尔顿模型的贡献与现代修正"],"prerequisites":["元素、单质、化合物是不同分类层次","下标表示一个实体内原子数，系数表示实体数"],"flow":["宏观质量守恒","原子重排","分子组成改变","原子学说的边界"],"deep":["模型不是物体的缩小照片，而是解释一组现象的简化规则。道尔顿把元素看成由特定原子组成，化合物由不同原子按整数个数结合；这让固定组成与质量守恒有了共同的微观解释。","化学反应改变电子分布及原子间连接，通常不改变原子核。氢和氧生成水时，是H、O原子重新分组，并非H原子变成O原子。反应前后的分子总数可以不同。","“同元素原子质量完全相同”被同位素修正；“原子不可再分”也不符合核结构事实。化学变化中原子种类近似守恒的模型仍有效，不能因模型有边界就把其适用结论全部否定。"],"derive":["以2H₂＋O₂→2H₂O为粒子账本：反应前H原子4、O原子2，反应后仍分别4、2；分子总数从3变2。该式只描述计量，不等于安全实验方案。","图中不同颜色代表不同元素，连在一起代表同一分子；粒子示意不表示真实比例、轨道或键角。氢氧混合物有爆炸风险，不自行点燃。"],"exam":["遇模型评价题分开写“能够解释的证据”与“不能解释的事实”，例如同位素反驳同元素原子等质量。","答原子是否守恒时注明普通化学反应；核反应不能直接套用。"],"examples":[{"q":"用2H₂＋O₂→2H₂O判断分子数和原子数是否均不变。","steps":["先按系数乘下标统计H：2×2＝4，产物2×2＝4。","O：1×2＝2，产物2×1＝2，所以各元素原子数守恒。","分子数为2＋1＝3变为2，不守恒；不可把原子守恒推广成分子数守恒。"],"ans":"原子数守恒，分子数3→2。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"把H₂、O₂分子图转成生成4个H₂O分子的粒子账本，至少各需几个反应物分子？","steps":["4个水分子共含8个H原子与4个O原子。","每H₂提供2H，需4个H₂；每O₂提供2O，需2个O₂。","写4H₂＋2O₂→4H₂O，最简系数为2∶1∶2。微粒账本满足原子守恒，不把生成分子数与反应物总数相等当条件。"],"ans":"4个H₂、2个O₂。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"同元素X有两类原子，核内质子都为6，中子分别6、7。这对道尔顿学说意味着什么？","steps":["质子数相同表示属于同元素；中子不同使质量不同。","这否定“同元素原子质量一律相等”的旧假设。","两类原子在普通化学反应中仍可按同元素原子计数，原子重排模型仍可使用。"],"ans":"旧等质量假设需修正；化学反应重排原子观点仍有效。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]}],"practice":[{"q":"基础：H₂、2H、2H₂分别表示什么？","steps":["H₂下标2表示一个氢分子中2个H原子。","2H为2个独立H原子；2H₂为2个氢分子，共4个H原子。"],"ans":"1分子／2原子／2分子4原子。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"理解：水由H、O组成，水的性质为什么不等于两种单质性质的平均？","steps":["水形成了不同连接和电子分布的新粒子。","组成元素保留不意味着化学性质保留；水是化合物，不是两种气体的简单混合。"],"ans":"结构改变导致性质改变。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"应用：3个O₂分子转变为2个O₃分子，比较氧原子数和分子数。","steps":["初态3×2＝6个O原子，末态2×3＝6。","原子数相同，分子数由3降为2；元素仍为O。"],"ans":"6个原子不变；分子数减少1。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"综合3.2：密闭装置中氢气和氧气生成水，反应后气体少了，能否说质量消失？","steps":["气体粒子数减少与总质量减少不是同一命题。","形成的水可能凝结，仍在装置内；各元素原子及装置总质量保持。","应称整个密闭装置，不能只称剩余气体。"],"ans":"不能；相态和粒子组合变化不破坏质量守恒。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":["3.2"]}],"quick":["模型用于解释证据；修正不等于全盘否定","化学反应通常守恒原子种类和数目，分子数可变"],"quiz":{"q":"检测：学生说“原子可以分，所以质量守恒错了”。指出推理中的范围错误。","steps":["原子核可变化属于核过程层次。","普通化学反应主要涉及电子和连接变化，不能用核过程否定其近似质量守恒。","若答不出范围，回读模型边界一段。"],"ans":"混淆核过程与普通化学反应的适用范围。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":3,"section_id":"3.1","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":2,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"3.2":{"goals":["分别应用质量守恒、定比、倍比定律","用开放与密闭系统解释称量差异"],"prerequisites":["比例与百分比运算","元素质量可以相加，质量比不同于原子数比"],"flow":["系统边界","质量守恒","同一化合物定比","不同化合物倍比"],"deep":["质量守恒要先确定系统：敞口酸与碳酸盐反应的容器会失重，因为CO₂跨过边界离开；把逸出气体也计入，反应物总质量仍等于产物总质量。称量只追踪某部分不能反驳守恒。","定比定律比较的是同一种纯化合物不同样品。水中H与O质量比约1∶8；水与过氧化氢是不同化合物，不能要求两者也满足同一个比值。","倍比定律先固定一种元素的质量，再比较另一元素。CO与CO₂各含12g C时，O分别16g、32g，呈1∶2；直接比较两个任意样品氧质量可能没有意义。定律适用教材中的固定组成化合物，混合物与某些非整比固体需另论。"],"derive":["由m(H)∶m(O)＝1∶8，可得水中H质量分数1/9，O为8/9；质量比的两数必须相加归一化。","密闭称量比较前后同一整套装置；温度恢复一致、天平调零、重复称量。若要收集气体验证，应由教师选安全反应，不能密封可能产生高压的刚性容器。"],"exam":["计算先写所用定律，再写系统是否有气体进出。","倍比题列出“每1g固定元素对应的另一元素质量”，最后才取整数比。"],"examples":[{"q":"12.0g Mg完全生成20.0g MgO，参与反应的O₂质量是多少？","steps":["总产物只有MgO，按质量守恒m(Mg)＋m(O₂)＝m(MgO)。","m(O₂)＝20.0−12.0＝8.0g。","氧来自空气，不能把它从总物料账本中遗漏；单位是质量g。"],"ans":"8.0g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"8.0g氧与某金属完全反应得20.0g纯氧化物，求金属质量和该氧化物中金属质量分数。","steps":["只有两种反应物进入该产物，质量守恒给m金属＝20.0−8.0＝12.0g。","金属分数12.0/20.0＝0.600＝60.0%。","两元素质量分数60%与40%合计100%；不能把8/12当成氧的质量分数。"],"ans":"12.0g；60.0%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"两种氧化物甲含C 3.0g、O 4.0g；乙含C 6.0g、O 16.0g。检验倍比关系。","steps":["固定C为1g：甲O/C＝4/3g；乙O/C＝16/6＝8/3g。","相比(4/3)∶(8/3)＝1∶2，是小整数比。","乙原样品氧为甲4倍，但C也2倍，不能直接答1∶4。"],"ans":"固定C后O质量比1∶2。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]}],"practice":[{"q":"基础：纯水中H∶O质量比1∶8，27g水中各多少？","steps":["H分数1/(1＋8)＝1/9，质量27/9＝3g。","O为27−3＝24g；3＋24＝27验算。"],"ans":"H 3g、O 24g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"理解：敞口碳酸盐与酸反应后烧杯减轻，是否违背守恒？","steps":["CO₂从烧杯系统逸出。","将逸出气体纳入质量总和，前后质量仍相等；烧杯自身不是封闭物料系统。"],"ans":"不违背；遗漏逸出的气体。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"应用：某纯氧化物金属占80%，15g样品含氧多少？","steps":["氧分数1−0.80＝0.20。","m(O)＝15×0.20＝3.0g；金属12g，两者合计15g。"],"ans":"3.0g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"综合3.5：氧化镁质量由4.8g镁增至8.0g，Mg＝24、O＝16，求原子数最简比。","steps":["先守恒得氧质量8.0−4.8＝3.2g。","分别除相对原子质量：Mg 4.8/24＝0.20，O 3.2/16＝0.20。","比1∶1，化学式MgO；质量比3∶2并非下标。"],"ans":"Mg∶O＝1∶1，MgO。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":["3.5"]}],"quick":["守恒先圈系统，定比限定同一纯物质","倍比先固定一种元素质量"],"quiz":{"q":"检测：同一化合物两个样品的元素质量比不同，先检查什么？","steps":["检查是否为纯物质、是否完全反应或完全分离、称量是否包括气体。","只有排除混合与测量误差，才讨论模型适用性；若只比较总质量，回读定比。"],"ans":"先查纯度、反应／分离完整性和系统边界。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":3,"section_id":"3.2","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":2,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"3.3":{"goals":["区分质量数、单原子相对质量与元素平均相对原子质量","完成同位素丰度加权计算"],"prerequisites":["原子由核和电子组成","加权平均为数值乘份额后求和"],"flow":["质子中子电子","质量单位u","单原子相对质量","同位素加权平均"],"deep":["原子序数Z决定元素身份，中子数变化形成同位素；增减电子形成离子，不会直接改变Z。质量数A是质子数与中子数之和，是整数计数，并不等于精确原子质量。","相对原子质量是质量比：把某原子质量除以碳-12原子质量的1/12，得到无量纲数。u是质量单位，Ar是纯数，因此“Ar＝23g”把两个层次混淆。","周期表元素Ar通常反映同位素丰度平均。35.5不是某个氯原子有半个中子，而是大量原子的统计结果；改变同位素丰度，样品平均质量也会改变。计算给出质量数近似代替同位素质量时，要说明是中学近似。"],"derive":["Ar＝m(原子)/[m(¹²C)/12]；分子与分母都为质量，单位约去。","两同位素Ar为a、b，轻同位素份额x时平均为ax＋b(1−x)。平均必须位于a与b之间；所有丰度之和为1。"],"exam":["同位素题先分清问的是单个原子还是元素平均；标清百分比化成小数。","丰度未知时列一次方程并检验0≤x≤1；不要把近似质量数当作高精度测量值。"],"examples":[{"q":"某元素两同位素质量近似35、37，丰度75%、25%，求平均Ar。","steps":["先统一份额：0.75与0.25，和为1。","Ar≈35×0.75＋37×0.25＝26.25＋9.25＝35.50。","结果在35与37之间且靠近35，符合轻同位素较多。"],"ans":"35.5，无单位。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"氯原子Z＝17，某同位素A＝37，其Cl⁻有多少质子、中子和电子？","steps":["质子仍17，中子37−17＝20。","Cl⁻比中性原子多1个电子，所以18个。","形成离子只改电子数，不把A改成38或Z改成18。"],"ans":"17质子、20中子、18电子。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"某元素同位素质量近似10、11，平均10.8，求轻同位素丰度。","steps":["设轻同位素份额x，则10x＋11(1−x)＝10.8。","11−x＝10.8，x＝0.20。","两份额20%与80%；代回2.0＋8.8＝10.8，合理。"],"ans":"20%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]}],"practice":[{"q":"基础：²³₁₁Na原子有多少质子、中子、电子？","steps":["Z＝11，所以质子11；中子A−Z＝23−11＝12。","中性原子电子数等于质子数，为11；Na⁺才少1电子。"],"ans":"11、12、11。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"理解：一个原子质量约3.984×10⁻²³g，1u≈1.660×10⁻²⁴g，求相对质量。","steps":["两者单位都是g，先除质量标准。","比值3.984×10⁻²³/(1.660×10⁻²⁴)＝24.0；无单位。"],"ans":"约24.0。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"应用：质量近似24与26的同位素各占一半，平均Ar是多少？","steps":["每一种份额均0.50。","平均24×0.50＋26×0.50＝25；25在两者之间。"],"ans":"25。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"综合5.2：²⁴Mg变成Mg²⁺后质量数、质子数和电子数如何变化？Z＝12。","steps":["失去的是2个电子，核未改变。","质量数仍24、质子数仍12，中子12。","电子由12变10；离子质量略减，但质量数不减2。"],"ans":"A＝24、质子12、电子10。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":["5.2"]}],"quick":["Z定元素，A＝Z＋中子数","Ar无单位；平均Ar要按丰度加权"],"quiz":{"q":"检测：算得两同位素20、22的平均Ar＝23，结果哪里不合理？","steps":["正丰度平均必须落在20至22之间。","23超出范围，需查丰度未除100、份额之和或代数错误；回读加权式。"],"ans":"超出加权平均的上下界。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":3,"section_id":"3.3","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":2,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"3.4":{"goals":["根据括号、结晶水计算式量和元素百分比","区分实验式、分子式及离子化合物化学式"],"prerequisites":["3.3相对原子质量","下标与括号乘法"],"flow":["化学式表示对象","统计原子数","求式量","元素质量分数"],"deep":["分子式只给每个分子内各元素原子个数，并未唯一给出连接方式；C₂H₆O可对应不同结构。实验式把原子个数约到最简比，C₆H₁₂O₆与CH₂O只在比例意义上相关，不能把一个葡萄糖分子画成一个CH₂O分子。","离子晶体没有可独立分离的NaCl分子，因此NaCl通常表示离子数的最简比；式量可对任意化学式求和，相对分子质量则用于有分子的物质。","括号外下标作用于整个原子团，结晶水系数作用于整组H₂O。计算CuSO₄·5H₂O时有9个O、10个H，而不只有硫酸根内4个O。元素质量百分比的分母必须为整个指定样品的式量。"],"derive":["若式中元素E有a个，则相对贡献aAr(E)，w(E)＝aAr(E)/式量。所有元素质量分数相加应为1。","Ca(NO₃)₂的N数2、O数6，式量40＋2×14＋6×16＝164；Ca质量分数40/164，而不是40/102。"],"exam":["先写原子计数表，再求和；不要边读式边心算遗漏括号。","问“式量”写无单位的数；问“摩尔质量”再写g·mol⁻¹。"],"examples":[{"q":"求Ca(OH)₂式量及氧的质量百分比；Ca＝40、O＝16、H＝1。","steps":["统计Ca 1、O 2、H 2。","式量＝40＋2×16＋2×1＝74。","O贡献32，w(O)＝32/74×100%≈43.2%；H贡献也计入分母。"],"ans":"74；43.2%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"求Al₂(SO₄)₃的式量及硫质量百分比；Al＝27、S＝32、O＝16。","steps":["原子数Al 2、S 3、O 12。","式量2×27＋3×32＋12×16＝54＋96＋192＝342。","硫分数96/342×100%≈28.1%；括号外3需同时乘S与O，式量无单位。"],"ans":"342；硫约28.1%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"CuSO₄·5H₂O式量249.5，CuSO₄部分159.5，求10.0g晶体含结晶水质量。","steps":["每单位晶体水贡献5×18＝90。","水分数＝90/249.5≈0.3607。","10.0×0.3607＝3.61g；无水盐应6.39g，两者合计10.0g。"],"ans":"约3.61g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]}],"practice":[{"q":"基础：C₆H₆的实验式是什么？","steps":["C与H原子数比6∶6，公除6得1∶1。","最简式CH，不改变原分子式C₆H₆。"],"ans":"CH。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"理解：为什么NaCl不宜称作分子式？","steps":["NaCl固体为延伸离子晶格。","化学式表示Na⁺与Cl⁻数比1∶1，没有独立NaCl分子。"],"ans":"它表示离子最简比。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"应用：Fe₂O₃式量160、Fe贡献112，40.0g样品中含多少Fe？","steps":["Fe分数112/160＝0.700。","m(Fe)＝40.0×0.700＝28.0g；剩余12.0g为O。"],"ans":"28.0g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"综合3.5：某物质实验式CH₂O，Mr＝90，求分子式并验算。","steps":["实验式量12＋2＋16＝30。","倍数90/30＝3，所以C₃H₆O₃。","其Mr＝36＋6＋48＝90，各下标一起乘3。"],"ans":"C₃H₆O₃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":["3.5"]}],"quick":["括号先展开；结晶水全部算","质量分数＝该元素贡献／整体式量"],"quiz":{"q":"检测：算Mg(NO₃)₂时只数3个O会造成什么？","steps":["括号外2应同时乘N、O，正确为N 2、O 6。","漏数O会低估总式量并高估Mg的质量百分比；回读原子计数。"],"ans":"应数6个O；总式量会算小。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.4","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":3,"section_id":"3.4","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":2,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"3.5":{"goals":["从元素质量或百分比求实验式与分子式","用电荷守恒写离子化合物化学式"],"prerequisites":["3.4式量与质量分数","比值约分、近似值与有效数字"],"flow":["元素质量","除Ar得原子数比","约为整数比","实验式","用Mr确定倍数"],"deep":["质量比例不是原子个数比例。先除以每种原子的相对质量，相当于把每堆质量换成可比较的粒子计数，再统一除以最小值。若出现1∶1.5，应整体乘2成2∶3，直接四舍五入会改变组成。","百分比法假设100g只是比例工具，不是声称实际取样100g。若样品只含C、H、O且其余质量已经测准，O可由差值求；若样品含其他未测元素，不能把全部差值都当O。","离子化合物由正负电荷总和为零决定比值，Ca²⁺与PO₄³⁻需最小公倍电荷6，形成Ca₃(PO₄)₂。交叉下标后还需约简，但不能把多原子离子内部下标改动。"],"derive":["实验式的倍数k＝Mr/实验式量，应接近正整数；若远离整数，检查实验数据、元素清单或所给Mr。","燃烧法中n(C)＝n(CO₂)，n(H原子)＝2n(H₂O)；产物里的O一部分来自外加O₂，原样品O要用质量差另求。"],"exam":["把元素、质量、除Ar结果、最简比列成四行，保留中间精度。","分子式写完反算百分含量与Mr，比只看整数漂亮更可靠。"],"examples":[{"q":"Fe 7.00g与O 3.00g组成氧化物，Fe＝56、O＝16，求化学式。","steps":["相对粒子数Fe 7/56＝0.125，O 3/16＝0.1875。","除以0.125得到1∶1.5，再乘2为2∶3。","写Fe₂O₃；质量比112∶48＝7∶3，符合原数据。"],"ans":"Fe₂O₃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"某只含C、H的物质有C 6.0g、H 1.0g，Mr＝56，求实验式和分子式。","steps":["除Ar得C 6/12＝0.50，H 1/1＝1.0，原子数比1∶2。","实验式CH₂，式量14。","倍数56/14＝4，分子式C₄H₈；反算C∶H质量48∶8＝6∶1符合。"],"ans":"CH₂；C₄H₈。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"0.600g仅含C、H、O的物质完全燃烧得CO₂ 0.880g、H₂O 0.360g；Mr＝60。求分子式。","steps":["n(C)＝0.880/44＝0.0200mol；n(H)＝2×0.360/18＝0.0400mol。","m(C)＝0.240g，m(H)＝0.0400g，原样品m(O)＝0.600−0.240−0.040＝0.320g，n(O)＝0.0200mol。","比1∶2∶1，实验式CH₂O，式量30；60/30＝2，所以C₂H₄O₂。","不能用CO₂和H₂O中的氧总和作样品氧；其中有外加氧气的贡献。"],"ans":"C₂H₄O₂。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]}],"practice":[{"q":"基础：Al³⁺与SO₄²⁻形成什么式？","steps":["正负电荷最小公倍数6，需2个Al³⁺、3个SO₄²⁻。","多于一个硫酸根要加括号，写Al₂(SO₄)₃；净电荷0。"],"ans":"Al₂(SO₄)₃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"理解：元素原子数比1∶1.333，合理最简整数比？","steps":["1.333近似4/3，应整体乘3。","得到3∶4，不能直接把1.333约为1；需确认数据精度支持该近似。"],"ans":"3∶4。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"应用：化合物C 40.0%、H 6.67%、O 53.33%，求实验式。","steps":["按100g计：C 40/12≈3.333，H 6.67/1＝6.67，O 53.33/16≈3.333。","除以3.333约1∶2∶1，实验式CH₂O。","百分比合计100%，结果一致。"],"ans":"CH₂O。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"综合3.6：4.99g CuSO₄·xH₂O失水后剩3.19g CuSO₄，M盐＝159.5、M水＝18，求x。","steps":["水质量4.99−3.19＝1.80g，水n＝1.80/18＝0.100mol。","盐n＝3.19/159.5＝0.0200mol。","x＝0.100/0.0200＝5；检验总摩尔质量249.5，0.0200mol应4.99g。"],"ans":"x＝5。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":["3.6"]}],"quick":["先除Ar再约比，分子式还需Mr","燃烧产物中的O不能直接归给原样品"],"quiz":{"q":"检测：只知道实验式CH₂，能唯一确定分子式吗？","steps":["CH₂只给C∶H＝1∶2。","C₂H₄、C₃H₆等都符合，需要Mr或其他独立证据；回读倍数k。"],"ans":"不能，需要相对分子质量等证据。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.5","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":3,"section_id":"3.5","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":2,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"3.6":{"goals":["说明现代SI中mol的精确定义和指定实体","在质量、粒子数、气体体积间多步换算并检验条件"],"prerequisites":["3.3的Ar与3.4的式量","科学记数法、单位约分和化学式下标"],"flow":["质量m÷M","物质的量n","粒子数N＝nN_A","指定原子或离子数"],"deep":["物质的量n量度指定实体的数目；1mol恰含6.02214076×10²³个指定实体，这是现代SI定义，不再由12g碳-12样品来定义。实体可为原子、分子、离子或电子；“1mol氧”缺少对象。试卷若给N_A＝6.02×10²³mol⁻¹，数值计算按题给精度。","摩尔质量M＝m/n，是每摩尔样品质量；Mr是相对质量的无量纲比。在高中精度下，M以g·mol⁻¹表示时数值约等于Mr，不能因此省略M的单位或声称两概念相同。","气体摩尔体积V_m随温度、压强变化。理想气体V_m＝RT/p；273.15K、101.325kPa时约22.414L·mol⁻¹，100kPa时约22.711L·mol⁻¹。因此“标准状况”最好连同温压写出，先用题目给V_m；固液不能用气体摩尔体积。","1mol H₂SO₄分子中有4mol O原子、7mol总原子。先由分子转为指定原子，再乘N_A；若问溶液离子，要另给出电离模型，不能仅按化学式机械计数。"],"derive":["N＝nN_A，故n＝N/N_A；M＝m/n，故n＝m/M；V_m＝V/n，故n＝V/V_m。单位分别为1/(mol⁻¹)、g/(g·mol⁻¹)、L/(L·mol⁻¹)，均为mol。","由pV＝nRT除以np得V/n＝RT/p。用R＝8.314462618kPa·L·mol⁻¹·K⁻¹，必须用K和kPa，不能直接代摄氏温度。液态水若给体积，应先用密度求质量。"],"exam":["按“对象—条件—单位—转mol—转目标—复核”书写。遇体积数据先判定物态与温压，遇“原子数”圈出下标。","本轮未取得可核实到3.6的官方原题及评分表，以下均为原创训练，不给固定步骤分值或考频。"],"examples":[{"q":"9.00g H₂O含多少分子与H原子？M＝18.0g·mol⁻¹，N_A＝6.02×10²³mol⁻¹。","steps":["n(H₂O)＝9.00/18.0＝0.500mol。","N(H₂O)＝0.500×6.02×10²³＝3.01×10²³个分子。","每分子含2个H，n(H原子)＝1.00mol，N(H)＝6.02×10²³个。","分子数与H原子数不相同；质量以g除g·mol⁻¹得到mol，单位正确。"],"ans":"3.01×10²³个分子；6.02×10²³个H原子。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"3.01×10²³个NH₃分子质量多少，并含多少mol H原子？N_A＝6.02×10²³mol⁻¹，M＝17.0g·mol⁻¹。","steps":["n(NH₃)＝N/N_A＝0.500mol。","m＝0.500×17.0＝8.50g。","每分子3个H，所以n(H原子)＝3×0.500＝1.50mol；不是1.50mol NH₃。"],"ans":"8.50g；1.50mol H原子。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"11.2L CO₂在0℃、1atm，题给V_m＝22.4L·mol⁻¹、M＝44.0g·mol⁻¹，求质量；若11.2L为液态水可否照算？","steps":["CO₂已给气态条件，n＝11.2/22.4＝0.500mol。","m＝nM＝0.500×44.0＝22.0g。","液态水不可使用气体V_m；必须有密度，按m＝ρV后再除M求n。","22.4只属于指定条件下的近似，不是所有气体的永久常数。"],"ans":"CO₂质量22.0g；液态水不能照算。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]}],"practice":[{"q":"基础：4.60g Na有多少mol？M＝23.0g·mol⁻¹。","steps":["用n＝m/M，4.60/23.0＝0.200。","g约去g·mol⁻¹得mol，对象为Na原子。"],"ans":"0.200mol Na原子。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"理解：0.250mol H₂SO₄含多少O原子？N_A＝6.02×10²³mol⁻¹。","steps":["每分子含4个O，n(O)＝4×0.250＝1.00mol。","N(O)＝1.00×6.02×10²³＝6.02×10²³个；不能只乘一次分子物质的量。"],"ans":"6.02×10²³个。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"应用：某气体在题定条件V_m＝24.0L·mol⁻¹，体积6.00L，质量8.00g，求M。","steps":["n＝6.00/24.0＝0.250mol。","M＝m/n＝8.00/0.250＝32.0g·mol⁻¹；不能自动改用22.4。"],"ans":"32.0g·mol⁻¹。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"综合4.2.1：2H₂＋O₂→2H₂O，0.300mol H₂与足量O₂完全反应，生成水多少g？M水＝18.0。","steps":["先按配平方程式取n比2∶2＝1∶1。","n(水)＝0.300mol，m＝0.300×18.0＝5.40g。","足量O₂保证H₂完全消耗；系数比不是质量比。"],"ans":"5.40g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":["4.2.1"]}],"quick":["明确实体；n＝m/M＝N/N_A","气态且条件确定时n＝V/V_m；V_m依赖T、p"],"quiz":{"q":"检测：等温等压下0.5mol O₂和0.5mol CO₂有相同体积、分子数和原子数吗？","steps":["理想气体同温同压V＝nRT/p，n相同所以V相同。","分子数均0.5N_A，相同；原子物质的量分别1.0mol和1.5mol，不同。","若漏下标，回读指定实体的转换。"],"ans":"体积、分子数相同；原子数不同。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":3,"primary_section":"3.6","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":3,"section_id":"3.6","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":2,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"},{"source_id":"bipm_mole","url":"https://www.bipm.org/en/si-base-units/mole","page_or_section":"SI base unit mole","version":"modern SI","access_date":"2026-11-17"},{"source_id":"nist_constants","url":"https://physics.nist.gov/cuu/pdf/all.pdf","page":6,"version":"2022 CODATA","access_date":"2026-11-17"}]}},"化学4":{"4.1.1":{"goals":["读出方程式的微观与宏观计量意义","正确标明物态和反应条件"],"prerequisites":["3.4化学式与3.6物质的量","化学变化与物理变化"],"flow":["事实与条件","反应物和生成物","守恒配平","读出物质的量比"],"deep":["化学方程式先建立物质身份，再表达数量关系。左、右的化学式来自实验事实；单凭守恒可以配出不真实的反应，所以先确认产物，不能靠改化学式使数目凑齐。","系数给实体数比和物质的量比，质量比还要各乘摩尔质量。2H₂＋O₂→2H₂O对应2mol、1mol、2mol，而非2g、1g、2g。","物态符号(s)、(l)、(g)、(aq)是状态信息，aq表示水溶液而非纯液体；催化剂、加热或光照写在箭头条件处。催化剂虽可参与机理步骤，净反应中再生，不应作为被消耗的计量反应物。"],"derive":["读2Mg(s)＋O₂(g)→2MgO(s)：原子Mg 2＝2、O 2＝2；质量48g＋32g＝80g，采用Mg＝24、O＝16的中学值。","方程式不能独自提供反应速率、是否完全或所有安全操作；镁燃烧强光与高温，示例只用于计量。"],"exam":["答解释题分别写化学式、系数比、物态与条件，避免只译成一句“发生反应”。","气体体积比等于系数比还需同温同压且参与比较的都是气体。"],"examples":[{"q":"解释N₂(g)＋3H₂(g)⇌2NH₃(g)的计量意义。","steps":["N₂、H₂、NH₃的物质的量比为1∶3∶2。","采用N＝14、H＝1时质量比为28∶6∶34，总质量守恒。","同温同压理想气体体积比也为1∶3∶2；双向箭头不表示任意时刻都会完全生成。"],"ans":"物质的量比1∶3∶2，质量比28∶6∶34。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]},{"q":"将BaCl₂(aq)与Na₂SO₄(aq)生成BaSO₄沉淀的反应写成净离子式，并核查电荷。","steps":["分子式BaCl₂＋Na₂SO₄→BaSO₄(s)＋2NaCl。","拆可溶强电解质，消去Na⁺和Cl⁻，得Ba²⁺＋SO₄²⁻→BaSO₄(s)。","左净电荷＋2−2＝0，右0，Ba、S、O均守恒；沉淀不拆成游离离子。"],"ans":"Ba²⁺＋SO₄²⁻→BaSO₄(s)。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]},{"q":"把“氯化钠水溶液与硝酸银水溶液生成氯化银沉淀”写成方程式。并写出净离子方程式。","steps":["反应物NaCl(aq)、AgNO₃(aq)，产物AgCl(s)、NaNO₃(aq)。","NaCl(aq)＋AgNO₃(aq)→AgCl(s)＋NaNO₃(aq)。","各元素均守恒，系数均1；aq不能写为l，AgCl为固体沉淀。","将aq强电解质拆为离子：Na⁺＋Cl⁻＋Ag⁺＋NO₃⁻→AgCl(s)＋Na⁺＋NO₃⁻。","删去两边相同的旁观离子Na⁺、NO₃⁻，得到Ag⁺＋Cl⁻→AgCl(s)。沉淀保留化学式；左净电荷0、右0，Ag与Cl均守恒。"],"ans":"NaCl(aq)＋AgNO₃(aq)→AgCl(s)＋NaNO₃(aq)。净离子式Ag⁺＋Cl⁻→AgCl(s)。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]}],"practice":[{"q":"基础：2CO＋O₂→2CO₂中CO与O₂的mol比？","steps":["直接读系数2与1。","这是物质的量比；CO摩尔质量28，质量比为56∶32。"],"ans":"2∶1。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]},{"q":"理解：方程式的“aq”意味着什么？","steps":["aq表示物质溶在水中。","l表示纯液态或指定液体，不提供溶液组成，两者不可交换。"],"ans":"水溶液状态。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]},{"q":"应用：2Mg＋O₂→2MgO，4mol Mg需多少mol O₂？","steps":["系数关系n(O₂)/n(Mg)＝1/2。","4×1/2＝2mol；先检查Mg氧化完全且O₂供应充分。"],"ans":"2mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]},{"q":"综合3.6：上题4mol Mg质量多少？Mg＝24g·mol⁻¹。","steps":["先明确4mol为Mg原子。","m＝nM＝4×24＝96g；不能把系数2误当成摩尔质量。"],"ans":"96g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":["3.6"]}],"quick":["系数比＝实体数比＝mol比","气体体积比另查温压，质量比需乘M"],"quiz":{"q":"检测：能否把H₂O改为H₂O₂来配平制水反应？","steps":["化学式规定物质身份，改下标会变成另一化合物。","配平只能调系数；若此项错，回读“事实先于配平”。"],"ans":"不能；只能改变系数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.1.1","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"4.1.2":{"goals":["按不同分类标准描述反应","识别分类重叠和分类条件"],"prerequisites":["元素、化合物与离子的区分","化合价与氧化数的基础"],"flow":["确定分类标准","检查反应特征","允许分类重叠","用方程式支持"],"deep":["化合、分解、置换、复分解是按反应物和产物形式分类，不是所有反应的完备互斥清单。燃烧可能同时是化合和氧化还原，不能把“燃烧”当成与四类必然互斥的第五格。","化合由多种物质生成一种，分解由一种生成多种。置换通常为单质与化合物反应产生另一单质；复分解常为两种化合物交换离子，水溶液中是否发生还需沉淀、气体、弱电解质等驱动力，不能只交换符号。","氧化还原以氧化数变化判断；中和以酸碱作用判断，属于不同标准。2Mg＋O₂→2MgO既化合又氧化还原；酸与碱生成盐和水通常属于复分解，元素氧化数通常不变。"],"derive":["Zn＋CuSO₄→ZnSO₄＋Cu：Zn从0升至＋2，Cu从＋2降至0；既置换又氧化还原。","AgNO₃＋NaCl→AgCl↓＋NaNO₃：Ag仍＋1、Cl仍−1，沉淀形成而非电子转移。"],"exam":["回答分类时明确依据，最好附一个可见特征；有多重分类时逐项说明。","不要把“溶液中交换离子”自动当成实际净反应。"],"examples":[{"q":"2KClO₃→2KCl＋3O₂属于化合还是分解？","steps":["反应物只有一种KClO₃，生成KCl、O₂两种物质。","按形式属于分解；系数2与3不是物质种数。","它还涉及氧化数改变，分类标准可以重叠。"],"ans":"分解反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]},{"q":"Na投入CuSO₄水溶液，是否能只按活动性顺序直接写Na置换出Cu？","steps":["Na与水迅速反应，水不是可忽略的惰性背景。","因此仅凭Na比Cu活泼不能保证直接获得Cu，随后还可能有碱与Cu²⁺反应等。","活动性顺序需配溶剂和反应条件；本题只作判断，不建议操作该反应。"],"ans":"不能，必须考虑Na与水等反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]},{"q":"HCl＋NaOH→NaCl＋H₂O是置换吗？","steps":["反应物都是化合物，没有单质置换另一单质。","H⁺与OH⁻形成水，属于酸碱中和，按形式也可归复分解。","不能因出现H就把氢离子当成H₂单质。"],"ans":"不是置换；是中和、复分解。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]}],"practice":[{"q":"基础：CaCO₃加热生成CaO和CO₂，归哪类？","steps":["一种化合物生成两种物质。","按形式为分解，写条件“加热”。"],"ans":"分解。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]},{"q":"理解：Mg燃烧可以既化合又氧化还原吗？","steps":["Mg和O₂生成一种MgO，符合化合。","Mg 0→＋2、O 0→−2，有电子转移，符合氧化还原。"],"ans":"可以，依据不同。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]},{"q":"应用：Fe＋CuSO₄→FeSO₄＋Cu，按形式分类。","steps":["Fe是单质，CuSO₄是化合物；生成另一单质Cu。","单质置换化合物中的元素，故置换。"],"ans":"置换反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]},{"q":"综合4.1.1：NaCl(aq)与KNO₃(aq)混合，交换成KCl、NaNO₃可否据此断定反应？","steps":["这些盐在该水溶液模型中均以离子存在。","交换前后离子种类和数量相同，无沉淀、气体等净变化。","写出形式上的交换式不能证明发生净反应。"],"ans":"不能；该情境无净离子反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":["4.1.1"]}],"quick":["先说分类依据，再说特征","分类可能重叠；形式可写不等于反应可发生"],"quiz":{"q":"检测：“所有复分解都是氧化还原”对吗？","steps":["看氧化数而非是否交换离子。","AgNO₃与NaCl生成沉淀时各元素氧化数不变，是反例；回读两种标准。"],"ans":"错，沉淀复分解可无氧化数变化。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.1.2","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"4.1.3":{"goals":["用元素守恒配平方程式并核对","在保留化学式的前提下取得最简整数系数"],"prerequisites":["化学式原子数统计","最小公倍数与线性方程"],"flow":["固定正确化学式","选择元素列守恒","求系数","最简化","全元素复核"],"deep":["配平把每种元素的原子数守恒转成方程组。未知量为化学式前系数，下标属于已知的物质组成。若反应物种类和产物种类给错，求得整数也不能保证化学事实正确。","观察法宜先处理出现次数少的元素；若多原子团完整保留，可作为整体统计，但最后仍要逐元素检查。含氧燃烧先平C、H，再平O；临时分数可以使用，最终整体乘最小公倍数。","离子方程式除了原子还需电荷守恒。本节以分子方程式为主，不能把原子数平衡误当作任何方程式都已充分平衡。"],"derive":["设aC₂H₆＋bO₂→cCO₂＋dH₂O：C给c＝2a，H给d＝3a，O给2b＝2c＋d＝7a。取a＝2，则b＝7、c＝4、d＝6。","验证C：4＝4；H：12＝12；O：14＝8＋6。系数2、7、4、6无公因数。"],"exam":["保留中间配平步骤，最后另列各元素核查；方程式若要用于计算，必须先平。","生成气体、沉淀及加热条件属于表达完整性，不能用来代替原子数检查。"],"examples":[{"q":"配平Fe＋O₂→Fe₂O₃。","steps":["产物有3个O，反应物O₂有2个，取氧最小公倍数6。","取2Fe₂O₃和3O₂，产物含4Fe，故左边4Fe。","4Fe＋3O₂→2Fe₂O₃；Fe 4＝4、O 6＝6，系数最简。"],"ans":"4Fe＋3O₂→2Fe₂O₃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]},{"q":"配平Na₂CO₃＋HCl→NaCl＋H₂O＋CO₂并检查。","steps":["Na有2个，右先取2NaCl，因此左取2HCl。","H为2，右1H₂O；C为1，右1CO₂。","O左3，右1＋2＝3，所有元素相等，系数1、2、2、1、1。"],"ans":"Na₂CO₃＋2HCl→2NaCl＋H₂O＋CO₂。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]},{"q":"配平Al₂(SO₄)₃＋Ca(OH)₂→Al(OH)₃＋CaSO₄。","steps":["保留SO₄与OH整体：1个Al₂(SO₄)₃需3个CaSO₄，因此3Ca(OH)₂。","2个Al对应2Al(OH)₃；OH左6、右6。","逐元素验算Al 2、Ca 3、S 3、O 18、H 6，均相等。"],"ans":"Al₂(SO₄)₃＋3Ca(OH)₂→2Al(OH)₃＋3CaSO₄。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]}],"practice":[{"q":"基础：配平H₂＋O₂→H₂O。","steps":["先使O相等，右取2H₂O。","右H为4，左取2H₂，得到2∶1∶2。"],"ans":"2H₂＋O₂→2H₂O。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]},{"q":"理解：Na＋H₂O→NaOH＋H₂为何不能改H₂为H？","steps":["H₂是氢气实际分子式。","应调系数：2Na＋2H₂O→2NaOH＋H₂，Na 2、O 2、H 4均守恒。"],"ans":"不能改物质身份；系数2、2、2、1。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]},{"q":"应用：配平C₃H₈＋O₂→CO₂＋H₂O。","steps":["C先取3CO₂，H取4H₂O。","右O为6＋4＝10，左取5O₂；各元素守恒。"],"ans":"C₃H₈＋5O₂→3CO₂＋4H₂O。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]},{"q":"综合3.6：上式完全燃烧0.200mol C₃H₈需多少mol O₂？","steps":["已平系数比O₂∶C₃H₈＝5∶1。","n(O₂)＝5×0.200＝1.00mol，不能用未平方程式1∶1。"],"ans":"1.00mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":["3.6"]}],"quick":["只调系数，不改下标","C、H先平，O后平；最后逐元素复核"],"quiz":{"q":"检测：2Fe＋3O₂→Fe₂O₃哪里错？","steps":["Fe左右均2，但O左6、右3。","需整体改成4Fe＋3O₂→2Fe₂O₃；若只查一种元素会漏错。"],"ans":"氧不守恒。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.1.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.1.3","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"4.2.1":{"goals":["把样品量转为mol后按系数求目标量","检验完全反应与气体状态条件"],"prerequisites":["3.6三种mol转换","4.1.3配平"],"flow":["已知质量或体积","已知mol","反应系数比","目标mol","目标质量或体积"],"deep":["化学计量的核心比例在物质的量层。相同系数的不同物质摩尔质量可不同，不能把质量直接按系数比例换算；先把给定量转为mol，跨越方程式，再转换为题目要的单位。","一般aA＋bB→cC中，A完全反应且其他反应物足量时，n(C)＝c·n(A)/a。若A不完全反应，应改用“实际消耗A的mol”，不能直接套初始投料。","同温同压理想气体体积比才可直接代替mol比；固体体积、不同温压气体体积不能直接作系数比。溶液浓度换算需体积用L，并以溶质mol参与比例。"],"derive":["由每发生一次反应进度ξ消耗aξ mol A、生成cξ mol C，故ξ＝n消耗(A)/a，目标为cξ。","质量通式m(C)＝[m(A)/M(A)]×(c/a)×M(C)。单位g/(g·mol⁻¹)×1×g·mol⁻¹＝g。"],"exam":["建议依次写配平式、已知mol、比例、目标量，方便发现漏系数和单位。","结果核对总质量不能超过系统全部反应物质量，但可超过某一个反应物的质量。"],"examples":[{"q":"CaCO₃完全分解：CaCO₃→CaO＋CO₂；10.0g CaCO₃产生CO₂多少g？M为100、56、44。","steps":["n(CaCO₃)＝10.0/100＝0.100mol。","系数1∶1，n(CO₂)＝0.100mol。","m(CO₂)＝0.100×44＝4.40g；CaO为5.60g，两产物合计10.0g。"],"ans":"4.40g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]},{"q":"2CO＋O₂→2CO₂，5.60g CO完全反应生成CO₂多少g？M(CO)＝28.0、M(CO₂)＝44.0。","steps":["n(CO)＝5.60/28.0＝0.200mol。","按2∶2，CO₂为0.200mol，质量0.200×44.0＝8.80g。","增加的3.20g来自氧气，不能因产物大于CO投料就判不守恒。"],"ans":"8.80g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]},{"q":"2Al＋6HCl→2AlCl₃＋3H₂，5.40g Al与足量酸反应，题给V_m＝24.0L·mol⁻¹，求H₂体积。M(Al)＝27.0。","steps":["n(Al)＝5.40/27.0＝0.200mol。","n(H₂)＝0.200×3/2＝0.300mol。","V＝nV_m＝0.300×24.0＝7.20L；用题给状态，不改成22.4。"],"ans":"7.20L。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]}],"practice":[{"q":"基础：2Mg＋O₂→2MgO，0.30mol Mg生成多少mol MgO？","steps":["系数比2∶2＝1∶1。","Mg完全反应且氧足量时生成0.30mol。"],"ans":"0.30mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]},{"q":"理解：为何不能用10g CaCO₃直接得10g CO₂？","steps":["1∶1为mol比。","两物质M分别100与44，10g仅0.10mol，只得4.4g CO₂。"],"ans":"M不同，质量比100∶44。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]},{"q":"应用：N₂＋3H₂→2NH₃，0.50mol N₂完全反应需H₂多少g？M(H₂)＝2.00。","steps":["H₂物质的量0.50×3＝1.50mol。","质量1.50×2.00＝3.00g；注意H₂的M不是1。"],"ans":"3.00g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]},{"q":"综合3.6：CaCO₃分解得到4.40g CO₂，在V_m＝22.4L·mol⁻¹下体积多少？","steps":["n(CO₂)＝4.40/44＝0.100mol。","V＝0.100×22.4＝2.24L，明确气体及给定状态。"],"ans":"2.24L。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":["3.6"]}],"quick":["质量→mol→系数比→mol→目标量","比例使用消耗量，不一定是初始量"],"quiz":{"q":"检测：反应后有A剩余，还能用初始A计算全部产物吗？","steps":["不能，只有实际消耗量与生成量符合计量关系。","先用限量反应物或初始减剩余求消耗A；回读完全反应条件。"],"ans":"不能，要用实际消耗A。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.2.1","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"4.2.2":{"goals":["用质量分数分离有效反应物与杂质","在明确杂质性质时由产物反推纯度"],"prerequisites":["质量百分比","4.2.1化学计量"],"flow":["总样品","反应性与杂质假设","纯物质质量","化学计量","反算纯度"],"deep":["纯度是样品中目标物质质量占比，m纯＝m样×纯度。只有题目说明杂质不参与所研究反应、不贡献目标产物时，才能把全部产物都归于纯物质。","若杂质也能与酸放出同种气体，单测气体体积未必能唯一求纯度。若产物混有水汽或未收集完全，测得气体量也不等于理论产量。计算前应列出这些假设，而不是把数据一律视为理想。","纯度与产率作用在不同环节：纯度先决定有效投料，产率再决定实际产品。二者即使均为百分数，也不能互换其物理意义。"],"derive":["m纯＝wm样，0≤w≤1；若一对一生成气体，则m纯＝n气体M纯。","若求含杂样品需求，m样＝m纯/w。除以小于1的数会增加需求；乘w反会使所需样品不足。"],"exam":["先写“杂质不反应且不贡献目标产物”，再做纯度换算。","反推纯度大于100%时先查杂质反应、气体条件及收集方式。"],"examples":[{"q":"25.0g石灰石含CaCO₃ 80.0%，完全分解得CO₂多少g？杂质惰性；M为100、44。","steps":["m(CaCO₃)＝25.0×0.800＝20.0g。","n(CaCO₃)＝20.0/100＝0.200mol，CO₂同mol。","m(CO₂)＝0.200×44＝8.80g；杂质5g不纳入反应计量。"],"ans":"8.80g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]},{"q":"含CaCO₃的20.0g惰性杂质样品完全反应得CO₂ 6.60g，M为100、44，纯度多少？","steps":["n(CO₂)＝6.60/44＝0.150mol。","一对一对应CaCO₃质量0.150×100＝15.0g。","纯度15.0/20.0＝75.0%；前提是杂质不贡献CO₂、反应与收集完整。"],"ans":"75.0%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]},{"q":"10.0g含惰性杂质的CaCO₃样品与足量酸生成CO₂ 1.792L，V_m＝22.4。求纯度。","steps":["n(CO₂)＝1.792/22.4＝0.0800mol。","一对一得m(CaCO₃)＝0.0800×100＝8.00g。","w＝8.00/10.0＝0.800＝80.0%；需气体干燥且收集完全。"],"ans":"80.0%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]}],"practice":[{"q":"基础：40g含盐75%的样品含纯盐多少？","steps":["m纯＝40×0.75＝30g。","惰性杂质为10g，合计40g。"],"ans":"30g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]},{"q":"理解：杂质也放CO₂，能把全部CO₂归给CaCO₃吗？","steps":["不能；观测气体有多个来源。","需知道杂质种类、含量关系或增加独立测量，否则问题可能不唯一。"],"ans":"不能，需更多证据。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]},{"q":"应用：需20g纯CaCO₃，纯度80%的样品需多少g？","steps":["m样＝m纯/w＝20/0.80＝25g。","验算25×0.80＝20g，必须多于纯物质量。"],"ans":"25g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]},{"q":"综合4.2.4：25g、纯度80%的CaCO₃理论CO₂ 8.8g，实际收集7.04g，产率多少？","steps":["先由纯度确定理论产量8.8g，不按25g全部为CaCO₃。","产率＝7.04/8.8×100%＝80.0%。","两个80%含义不同，不能因此认为纯度等于产率。"],"ans":"80.0%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":["4.2.4"]}],"quick":["纯度决定有效投料","杂质是否也贡献产物必须先确认"],"quiz":{"q":"检测：算出纯度120%，可以写成“样品很纯”吗？","steps":["纯度为质量分数不应大于100%。","检查气体温压、误把杂质产物计入、湿气或计量系数；回读模型假设。"],"ans":"不能，模型或数据处理有误。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":2,"question_no":1,"source":"https://duzhongacademy.com/pastpapers/uec-2025/chemistry/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.2.2","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"4.2.3":{"goals":["用n/系数判断限量反应物","计算过量物剩余量并解释反应进度"],"prerequisites":["4.2.1 mol比例","4.2.2有效投料"],"flow":["分别求初始mol","除各自系数","最小值决定反应进度","产物与剩余"],"deep":["限量判断不能比较质量大小，也不能只比较mol大小。每种反应物承担的系数不同，应该把可支持的反应次数n/a放在同一尺度上；最小者先耗尽，决定产物上限。","过量物不是“不反应”：它也按比例被消耗，只是有剩余。计算n剩＝n初−系数×反应进度，并检查剩余不为负。若算负数，说明选错限量物或系数。","这一模型假设按指定反应完全转化到限量物耗尽；可逆平衡、速率不足或副反应会使实际产量更低，应与产率和反应限度分开。"],"derive":["对aA＋bB→cC，ξ_max＝min[n₀(A)/a,n₀(B)/b]。则n(C)＝cξ_max，A剩n₀(A)−aξ_max。","用一套ξ同时求各物质可防止把两种投料各算一次产物再相加的错误。"],"exam":["把每种反应物都列到表中，不以“题目先给谁”判断谁完全反应。","最后同时报告限量物、产物和剩余，并用原子或总质量复核。"],"examples":[{"q":"N₂＋3H₂→2NH₃，1.00mol N₂与2.00mol H₂充分反应，求限量物和NH₃。","steps":["N₂可支持ξ＝1.00，H₂可支持ξ＝2.00/3＝0.667mol。","H₂较小，为限量物；n(NH₃)＝2×2/3＝1.33mol。","N₂消耗2/3mol，剩1/3＝0.333mol；H₂剩0。"],"ans":"H₂限量；NH₃ 1.33mol；N₂剩0.333mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]},{"q":"N₂＋3H₂→2NH₃，初始2.00mol N₂与3.00mol H₂，生成NH₃及剩余N₂各多少？","steps":["可支持反应进度分别2.00/1＝2.00、3.00/3＝1.00mol。","H₂限量，生成2×1.00＝2.00mol NH₃。","N₂消耗1.00mol，剩2.00−1.00＝1.00mol；不是所有氮都反应。"],"ans":"NH₃ 2.00mol；N₂剩1.00mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]},{"q":"2H₂＋O₂→2H₂O，4.00g H₂与16.0g O₂完全反应，M为2、32、18。","steps":["H₂为2.00mol，O₂为0.500mol。","n/系数分别1.00与0.500，O₂限量。","生成H₂O 2×0.500＝1.00mol＝18.0g。H₂消耗1.00mol＝2.00g，剩2.00g。","总投料20.0g＝水18.0g＋剩氢2.00g，质量守恒。"],"ans":"O₂限量；水18.0g；剩H₂ 2.00g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]}],"practice":[{"q":"基础：A＋2B→C，A 3mol、B 4mol，谁限量？","steps":["A/1＝3，B/2＝2。","B可支持的反应进度较小，所以B限量，C 2mol。"],"ans":"B。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]},{"q":"理解：上题A是否完全不反应？","steps":["ξ＝2mol，A消耗2mol。","A剩3−2＝1mol；过量表示有剩余，不表示未参与。"],"ans":"参与2mol，剩1mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]},{"q":"应用：2Mg＋O₂→2MgO，Mg 0.30mol、O₂ 0.10mol，求MgO。","steps":["n/系数Mg为0.15、O₂为0.10，O₂限量。","MgO＝2×0.10＝0.20mol；Mg剩0.10mol。"],"ans":"0.20mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]},{"q":"综合4.2.2：12g、纯度80%的Mg与足量O₂反应，M(Mg)＝24、M(MgO)＝40，求MgO。","steps":["有效Mg＝12×0.80＝9.6g，为0.40mol。","氧足量，Mg限量；按2∶2生成MgO 0.40mol。","m＝0.40×40＝16g；产物氧质量来自外加O₂，故可大于有效Mg质量。"],"ans":"16g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":["4.2.2"]}],"quick":["限量比较n/系数","剩余＝初始−系数×同一反应进度"],"quiz":{"q":"检测：1mol N₂与2mol H₂中，N₂ mol较少是否就限量？","steps":["所需比为1∶3。","1mol N₂需3mol H₂，实际只有2mol，所以H₂限量；回读n/系数。"],"ans":"不是，H₂限量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":2,"question_no":1,"source":"https://duzhongacademy.com/pastpapers/uec-2025/chemistry/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.2.3","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]},"4.2.4":{"goals":["区分理论产量、实际产量与产率","综合纯度和限量确定合理的理论基准"],"prerequisites":["4.2.3限量物","百分数与测量误差"],"flow":["有效投料","限量判断","理论产量","实际纯产品","产率与误差解释"],"deep":["理论产量是假设按指定反应完全生成目标产物时的最大量，须由有效且限量的反应物决定。实际产量是在实际操作与分离后取得的目标产品量，反应未完全、副反应、转移或过滤损失都可能使其降低。","产率＝实际产量/理论产量×100%，分子分母必须对应同一种物质、相同计量单位。若称得湿晶体或含杂产品，表观质量可能高于理论，不能解释成“原子变多”。","纯度与产率串联时先对投料用纯度，再做反应比例，最后乘产率；反推所需原料时顺序逆过来，用实际需求除产率、再除纯度。所有百分数计算需先化成小数。"],"derive":["η＝m实际/m理论，m实际＝ηm理论；同一产品也可用mol比求η。","η≤1是理想纯产品计量模型中的检查；测得η＞1提示干燥、纯度、称量或理论基准有问题。"],"exam":["先把理论量的来源写清，不直接拿投料质量当分母。","解释低产率时区分反应损失与分离损失，避免笼统写“实验不准”。"],"examples":[{"q":"理论可得10.0g产品，实际纯产品8.20g，求产率。","steps":["η＝8.20/10.0＝0.820。","转为百分数82.0%；两量都是同一纯产品质量，单位g约去。","短少1.80g可能源于转化和分离过程，单凭数字不能唯一判断原因。"],"ans":"82.0%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]},{"q":"理论目标产品0.250mol、实际纯产品0.200mol，产率是多少？若M＝80g·mol⁻¹，用质量核查。","steps":["同一种产品可用mol比：0.200/0.250＝0.800。","质量分别16.0g和20.0g，16.0/20.0仍为0.800。","产率80.0%，不要把20%损失比例当成产率。"],"ans":"80.0%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]},{"q":"12.5g、纯度80%的CaCO₃完全分解，CO₂收集产率90%；M为100、44，求收集质量。","steps":["有效CaCO₃＝12.5×0.80＝10.0g＝0.100mol。","理论CO₂＝0.100×44＝4.40g。","实际＝4.40×0.90＝3.96g；纯度作用于原料，产率作用于产品。"],"ans":"3.96g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]}],"practice":[{"q":"基础：理论20g、实际15g，产率？","steps":["同种产品比较15/20＝0.75。","写百分数75%；不是短少量5/20＝25%。"],"ans":"75%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]},{"q":"理解：湿产品称得产率105%，是否说明反应超额创造质量？","steps":["水或杂质被计入了产品质量。","纯产品实际量仍应按正确理论基准检查，需干燥、纯度校正。"],"ans":"不是；表观质量含水或杂质等。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]},{"q":"应用：需实际纯产品9g，产率75%，理论应达多少？","steps":["m理论＝m实际/η＝9/0.75＝12g。","验算12×0.75＝9g，理论量大于实际需求。"],"ans":"12g。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]},{"q":"综合4.2.3：N₂＋3H₂→2NH₃；1mol N₂、1.5mol H₂，NH₃实际0.80mol，求产率。","steps":["n/系数分别1和0.5，H₂限量。","理论NH₃＝2×0.5＝1.0mol。","产率0.80/1.0×100%＝80%；不能以2mol NH₃作分母。"],"ans":"80%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":["4.2.3"]}],"quick":["理论量由有效限量物决定","产率＝实际纯产品／理论同种产品"],"quiz":{"q":"检测：称量前产品未干燥，会怎样影响表观产率？","steps":["残留水增加称得质量，使分子偏大。","理论量不变，所以表观产率偏高；若把它当反应更完全，回读实际纯产品定义。"],"ans":"偏高，须先干燥或校正。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":4,"primary_section":"4.2.4","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":2,"question_no":1,"source":"https://duzhongacademy.com/pastpapers/uec-2025/chemistry/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"化学","subject_code":"chemistry","chapter_id":4,"section_id":"4.2.4","content_sources":[{"source_id":"dz_chemistry","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":4,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"chemistry_standard","page":3,"version":"官网文件；年份见来源审查","access_date":"2026-11-17"}]}},"物理3":{"3.1":{"goals":["根据研究问题判断质点模型是否合适","用位置随时间改变描述机械运动"],"prerequisites":["长度与时间单位","整体平移与自身转动的区别"],"flow":["研究对象","比较尺寸与问题尺度","质点模型","位置随时间变化"],"deep":["质点是把物体的质量集中到一个无尺寸点的模型；是否能用取决于问题而非物体本身大小。研究地球绕日公转轨道可忽略地球尺寸，研究昼夜自转就必须保留空间结构。","机械运动关注物体相对所选参照系的位置随时间改变。水分子运动也可研究，但温度是大量粒子统计的描述，不能把“物体变热”直接等同于整个物体发生位移。","先写想求的量：若求车头通过隧道的时刻，可以追踪车头点；若求整列火车完全离开隧道，就必须把列车长度纳入。模型简化的价值在于去掉无关细节，边界在于不能去掉题目需要的几何信息。"],"derive":["质点位置可写为x(t)。对平移车厢，车尾坐标x尾＝x头−L；若只知车头过桥，不能推出车尾已离桥。","无必需的新实验：可用同一段视频分别追踪车头点和车尾点，记录时间与坐标，核对模型是否遗漏长度。"],"exam":["模型判断用“所求量＋能否忽略尺寸”的因果句，不能答“大物体不能当质点”。","有长度的过桥题先画首末状态，再决定代表点需移动的距离。"],"examples":[{"q":"研究一列长100m火车从车头入300m隧道到车尾离开，能忽略车长吗？","steps":["初态车头在入口，末态车尾在出口。","此时车头位于出口前100m，因此车头总移动300＋100＝400m。","若忽略尺寸只算300m会少算100m，所以不能直接忽略车长。"],"ans":"不能；代表点需移动400m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"研究卫星绕地球的运行周期与卫星太阳能板转动，是否都能把整星当质点？","steps":["求整星轨道周期通常只需质心轨道，尺寸相对轨道可忽略时可作质点。","太阳能板转动需要轴、尺寸和不同点的位置，质点模型会删去所求信息。","同一卫星因问题不同采用不同模型，不依据“大或小”一刀切。"],"ans":"轨道可近似；板转动不可只用整星质点。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"研究地球一年公转与一天自转，分别能否用地心质点？","steps":["公转轨道尺度远大于地球直径，若求地心轨道，质点近似合适。","自转涉及不同位置绕轴的运动，质点没有大小和轴向，无法描述。","判断依据是研究目标与尺度，不是地球大或小。"],"ans":"地心公转可近似；研究自转不可。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]}],"practice":[{"q":"基础：小球沿直线位置随时间改变，属于什么运动？","steps":["固定参照系后，小球位置发生变化。","这符合机械运动定义，不需要先知道力或加速度。"],"ans":"机械运动。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"理解：所有小物体都可当质点吗？","steps":["若研究小陀螺的转动，需要其形状与转轴。","即使很小也不能忽略决定问题的结构。"],"ans":"不一定，取决于研究目标。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"应用：60m列车以10m/s完全通过140m桥，需多久？","steps":["车头从入桥到车尾离桥共移动140＋60＝200m。","匀速时间200/10＝20s；需完整通过而非仅车头到出口。"],"ans":"20s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"综合3.2：两辆车并行时从车内看对方静止，从地面看运动，是否矛盾？","steps":["两个观察分别选本车与地面参照系。","位置变化相对参照系描述，两个结论可同时成立；先注明参照系。"],"ans":"不矛盾，参照系不同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":["3.2"]}],"quick":["质点取决于研究目标","过桥全通过：代表点移动桥长＋车长"],"quiz":{"q":"检测：求足球自旋转速时只记录球心位置够吗？","steps":["球心静止也可自转。","自旋需要球面标记或角位移信息；只记录球心会丢失所求量，回读模型边界。"],"ans":"不够，需要转动信息。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.1","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.2":{"goals":["建立原点、正方向和单位一致的坐标描述","在匀速平移参照系间转换位置与速度"],"prerequisites":["3.1参照系与质点","带符号代数运算"],"flow":["参照物","坐标原点与正方向","位置坐标","相对位置与速度"],"deep":["参照物提供运动比较的对象，坐标系负责把比较结果量化。原点改变会改变坐标数值，但对同一参考系中两时刻作差，位移不受恒定原点平移影响。","设车A相对地面位置x_A，车B为x_B，则A相对B的位置为x_A−x_B。同一方向约定下，匀速平移时v_A/B＝v_A−v_B；必须先带正负，不能见“相对”就总用速率相减。","地面在很多短时实验中可近似为惯性系，加速车厢一般不是。参照系选择不改变事件本身，但会改变观察到的轨迹与速度；本章常加速度公式应和统一的时间、方向约定配合使用。"],"derive":["取新原点相对旧原点固定于x＝c，新坐标x′＝x−c；Δx′＝(x₂−c)−(x₁−c)＝Δx。","若B从原点匀速V运动，x′＝x−Vt，故v′＝v−V；此处只用经典、匀速平移情境。"],"exam":["开头写参照系、原点和正方向，使所有位移、速度符号统一。","计算相对量时给下标，避免把“地面速度”与“车内速度”混用。"],"examples":[{"q":"向东为正，A以20m/s向东、B以15m/s向东，A相对B速度？","steps":["地面速度v_A＝＋20、v_B＝＋15。","v_A/B＝20−15＝＋5m/s。","正号仍表示向东；B看A向前5m/s。"],"ans":"5m/s向东。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"地面坐标中A在＋50m、B在＋20m，原点改到旧坐标＋100m，求A相对B位置并核查。","steps":["原坐标相对位置x_A−x_B＝50−20＝＋30m。","新坐标A＝−50m、B＝−80m，差(−50)−(−80)＝＋30m。","共同平移原点不改变相对位置；位置负号不代表距离负。"],"ans":"＋30m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"改为B向西15m/s，A相对B速度？","steps":["同一正方向下B速度应写−15。","v_A/B＝20−(−15)＝＋35m/s。","相向运动的接近速率为35，不能用20−15＝5。"],"ans":"35m/s向东。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]}],"practice":[{"q":"基础：建立一维坐标系要规定哪三件事？","steps":["先指定零坐标的原点。","再定正方向与长度单位，才有可复查的数值。"],"ans":"原点、正方向、单位。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"理解：原坐标x从3m到8m，原点移到旧坐标10m处，位移变化吗？","steps":["新坐标为−7m到−2m。","位移(−2)−(−7)＝＋5m，与原8−3相同。"],"ans":"不变，＋5m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"应用：人在向东10m/s车内向西走2m/s，地面速度？","steps":["v人/车＝−2，v车/地＝＋10。","v人/地＝−2＋10＝＋8m/s。"],"ans":"8m/s向东。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"综合3.4：两车初距100m同向速率20与15m/s，后车更快，追上时间？","steps":["用前车为参考，间距减少速率20−15＝5m/s。","t＝100/5＝20s；也可写地面位置20t＝100＋15t验算。"],"ans":"20s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":["3.4"]}],"quick":["位置、速度的符号都依赖同一方向约定","相对速度v_A/B＝v_A−v_B"],"quiz":{"q":"检测：相向车的速率都为10m/s，相对速度是否为0？","steps":["在同一坐标中写＋10与−10。","相对速度差为20m/s；若写0说明只用了速率未写方向，回读符号约定。"],"ans":"不是，相对速率20m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.2","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.3":{"goals":["按路径计算路程、按始末计算位移","用绝对值区分位移与位移大小"],"prerequisites":["3.2带符号坐标","线段长度与矢量的区别"],"flow":["轨迹分段","各段长度相加为路程","末减初为位移","比较大小"],"deep":["路程累加实际走过的路径，不因折返而抵消；位移是初位置到末位置的矢量。直线坐标中Δx可正、负或零，路程始终非负，位移大小为","Δx","。","三角不等式解释路程≥位移大小：分段向量相加的合向量长度不大于各段长度和。等号要求各段沿同一直线同一方向，不能只说“直线运动就相等”。","闭合一圈始末相同，位移为零但路程等于周长。后续平均速度按位移，平均速率按路程，两种“平均”分子的含义不能混用。"],"derive":["分段位置x₀,x₁,…,x_n时，路程＝Σ","x_i−x_(i−1)","，位移＝x_n−x₀。","若有转向点须把路径在该点切开；只用起末坐标无法恢复路程。"],"exam":["先列位置顺序，再逐段求长度。答位移时写方向或正负号。","读图看清纵轴是位置还是累计路程，累计路程不会随时间下降。"],"examples":[{"q":"质点从−2m到＋5m，再回到＋1m，求路程与位移。","steps":["两段长度为","5−(−2)","＝7m和","1−5","＝4m。","路程7＋4＝11m；位移1−(−2)＝＋3m。","11≥3，符合检查；第二段反向不能从路程中扣除。"],"ans":"路程11m，位移＋3m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"沿直线从0走到＋6m，再到−2m，求路程、位移及位移大小。","steps":["路径两段长度6m与","−2−6","＝8m，路程14m。","位移−2−0＝−2m，大小2m。","14≥2符合检查；末位置负不意味着后段路径长为负。"],"ans":"14m；−2m；2m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"向东走3m再向北走4m，求位移大小与方向。","steps":["路程3＋4＝7m。","位移分量东3、北4，大小√(3²＋4²)＝5m。","相对东向夹角tan⁻¹(4/3)≈53.1°，指向东北；合成矢量不是路径。"],"ans":"位移5m，东偏北53.1°；路程7m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]}],"practice":[{"q":"基础：400m跑道一圈回原点，路程与位移？","steps":["路程为一圈长度400m。","末位置等于初位置，位移0。"],"ans":"400m，0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"理解：位移为−5m，位移大小是多少？","steps":["负号给方向而非负的长度。","位移大小","−5","＝5m。"],"ans":"5m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"应用：从x＝4m到−3m再到0，求路程。","steps":["分段长度7m和3m。","总路程10m，位移0−4＝−4m，二者不同。"],"ans":"10m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"综合3.6：上题总用时5s，求平均速度、平均速率。","steps":["平均速度＝位移/时间＝−4/5＝−0.80m/s。","平均速率＝路程/时间＝10/5＝2.0m/s；单位相同而意义不同。"],"ans":"−0.80m/s；2.0m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":["3.6"]}],"quick":["路程看过程，位移看始末","检查路程≥位移大小"],"quiz":{"q":"检测：直线往返一定有路程等于位移大小吗？","steps":["折返各段在位移中相消，路程中相加。","只有无转向的单向直线运动才可等大，回读三角不等式条件。"],"ans":"不一定；折返通常不等。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.3","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.4":{"goals":["用带符号位置方程解匀速追及相遇","区分速度和速率并进行单位换算"],"prerequisites":["3.3位移","代数一次方程与单位换算"],"flow":["速度大小方向恒定","x＝x₀＋vt","两位置相等","相遇条件"],"deep":["匀速直线运动要求任意等时间位移相同，大小、方向均不变。只在某一段算出一个平均值并不能证明运动匀速。匀速圆周虽速率不变，方向改变，不能用一维匀速直线模型。","位置方程x＝x₀＋vt把起始位置与后续位移分开。追及题两车路程可能不同，但相遇时在同一参考系、同一时刻位置相同；不同出发时间需为迟出发者写(t−延迟)。","km/h转m/s乘1000/3600＝1/3.6。先统一单位再代数，可防止把72km/h与秒直接相乘导致1000倍或3600倍错误。"],"derive":["v＝Δx/Δt在本模型恒定，所以Δx＝vΔt；加初始坐标得x(t)。","相向物体若起点相距L，方程v₁t＝L−v₂t，得t＝L/(v₁＋v₂)；两速率均取正数时此式只适用于相向接近。"],"exam":["追及只写一个共同的时间变量，标出每辆车x₀与带方向速度。","求得t应在两物体运动时间范围内，负根通常表示未来不会按该模型相遇。"],"examples":[{"q":"A从0以6m/s向右，B从60m以4m/s向右，何时相遇？","steps":["x_A＝6t，x_B＝60＋4t。","相遇6t＝60＋4t，t＝30s。","位置A＝180m，B＝60＋120＝180m，代回复核。"],"ans":"30s，x＝180m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"A以4m/s从0出发，5s后B从同一点以6m/s追赶，B出发后多久追上？","steps":["B出发时A领先4×5＝20m。","此后接近速率6−4＝2m/s，B需20/2＝10s。","若用从A出发计时t，4t＝6(t−5)得t＝15s，减5后仍10s。"],"ans":"B出发后10s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"车速72km/h，长80m，完全通过120m隧道要多久？","steps":["72/3.6＝20m/s。","车头需移动120＋80＝200m。","t＝200/20＝10s；车头到出口只需6s，区别由模型状态决定。"],"ans":"10s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]}],"practice":[{"q":"基础：54km/h等于多少m/s？","steps":["54×1000/3600＝15。","单位km、h按换算消去，得到m/s。"],"ans":"15m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"理解：速率不变是否必为匀速直线运动？","steps":["还需方向恒定且轨迹为直线。","圆周运动给出速率不变而速度改变的反例。"],"ans":"不是，还要方向不变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"应用：x₀＝−10m、v＝＋3m/s，5s时位置？","steps":["x＝−10＋3×5＝＋5m。","位移为15m，不等于末位置5m。"],"ans":"＋5m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"综合3.2：相距90m两人相向速率2、1m/s，多久相遇？","steps":["选第一个人起点为0，另一人起点90。","2t＝90−t，3t＝90，t＝30s；位置60m。"],"ans":"30s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":["3.2"]}],"quick":["x＝x₀＋vt；相遇令两位置相等","速度有方向，速率为其大小"],"quiz":{"q":"检测：A晚出发5s，能直接用同一t写x_A＝v_At吗？","steps":["若t从另一物体出发时计，A运动时间为t−5。","应写x_A＝x_A0＋v_A(t−5)，并限t≥5s；回读共同时间起点。"],"ans":"不能，需处理延迟。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.4","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.4","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.5":{"goals":["从位置图斜率求速度、速度图面积求位移","解释不同图中交点的不同意义"],"prerequisites":["3.4匀速方程","斜率和矩形面积"],"flow":["识别坐标轴","s–t斜率","v–t有向面积","判交点意义"],"deep":["图线的几何外观不能脱离坐标轴解释。位置—时间图中的水平线表示位置不变；速度—时间图中的水平线表示速度恒定，除非位于零轴，否则物体仍在运动。","位置图两条直线相交，说明同一时刻位置相同；速度图相交只说明速度相同，相遇还需要累计位移及初始位置信息。","速度图下方面积的符号来自速度方向。负速度矩形贡献负位移，若问路程则对各段面积取绝对值。位置图面积一般没有本章直接使用的路程含义。"],"derive":["x＝x₀＋vt的斜率Δx/Δt＝v；斜率单位m/s。v–t矩形面积vΔt，单位(m/s)·s＝m，对应位移。","图像斜率求值应使用两点坐标差，不能默认截距为零；画图需标轴名、单位、刻度和分段时间。"],"exam":["先写轴名再进行斜率或面积运算。","相遇题从x–t读交点；v–t题先把初始间距和面积合起来判断。"],"examples":[{"q":"x–t直线过(0s,5m)、(4s,13m)，求速度。","steps":["斜率(13−5)/(4−0)＝2m/s。","不是13/4，因为x₀＝5m不为零。","方程x＝5＋2t，代t＝4得13m，验证。"],"ans":"＋2m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"位置图0–2s由1m直线上升至5m，2–4s保持5m，求两段速度和全程平均速度。","steps":["第一段斜率(5−1)/2＝2m/s。","第二段位置不变，速度0；全程位移4m、时间4s，平均速度1m/s。","水平位置图表示静止，不表示以5m/s匀速。"],"ans":"2m/s、0；全程1m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"v–t图0–3s为＋4m/s，3–5s为−2m/s，求位移与路程。","steps":["前段面积4×3＝12m；后段面积−2×2＝−4m。","位移12−4＝8m。","路程12＋4＝16m；图下负面积不是负路程。"],"ans":"位移＋8m；路程16m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]}],"practice":[{"q":"基础：x–t图水平，物体怎样运动？","steps":["纵坐标位置不变。","Δx＝0，速度为零，而不是速度恒为某个非零值。"],"ans":"静止。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"理解：两物体v–t相交是否说明相遇？","steps":["只知道同一时刻速度相等。","还需位置或累计位移，初始距离可使它们仍分开。"],"ans":"不能直接说明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"应用：v＝−3m/s保持4s，位移多少？","steps":["矩形有向面积(−3)×4＝−12m。","负号给方向，路程为12m。"],"ans":"−12m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"综合3.4：A位置x＝2t，B＝10＋t，两条x–t线交点？","steps":["2t＝10＋t，t＝10s。","位置20m，含义为两者同处；速度仍分别2和1m/s。"],"ans":"(10s,20m)，相遇。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":["3.4"]}],"quick":["x–t斜率是v，v–t面积是位移","交点意义由坐标轴决定"],"quiz":{"q":"检测：x–t图下降是否表示“物体往坡下走”？","steps":["图的纵轴是位置坐标而非地形高度。","下降只说明速度为负，不能推断道路坡度；回读图像不是轨迹。"],"ans":"不能，只说明坐标减小。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.5","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.5","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.6":{"goals":["由总位移与总时间求平均速度","解释瞬时速度及等时、等路程平均的区别"],"prerequisites":["3.3位移和路程","3.5割线斜率"],"flow":["选定时间区间","总位移／总时间","缩小区间","瞬时速度"],"deep":["平均速度描述整个区间的净位置变化率；平均速率描述累计路程率。同一往返过程可有平均速度零、平均速率正，二者不是互相近似的同一个量。","瞬时速度是位置—时间曲线在该点的切线斜率，可理解为时间间隔趋于零时平均速度的极限。只取“很短”并不自动精确，实验中还受计时与位置分辨率限制。","前后等时间的两段匀速运动，速度按相同时间权重平均；等路程而速度不同时，慢的一段用时更多，平均速率应偏向慢值。回到原点求平均速度则为零，不能套等路程平均速率公式。"],"derive":["等路程L两段时间L/v₁、L/v₂，总路程2L，所以平均速率＝2v₁v₂/(v₁＋v₂)。这里v₁、v₂均为正速率。","只有速度随时间线性变化的匀加速度直线运动，区间平均速度才等于(u＋v)/2；一般变速不成立。"],"exam":["题目先圈“平均速度”还是“平均速率”，再写总量相除。","分段速度不能无条件直接算术平均，写出各段时间最可靠。"],"examples":[{"q":"去程100m速率5m/s，原路返回速率2m/s，求全程两种平均。","steps":["去程20s，回程50s，总70s。","总位移0，所以平均速度0。","总路程200m，平均速率200/70≈2.86m/s；不是(5＋2)/2。"],"ans":"平均速度0；平均速率2.86m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"单向运动前2s速度3m/s、后2s速度7m/s，全程平均速度？为何这里可算术平均？","steps":["两段位移6m与14m，共20m、总4s。","平均速度20/4＝5m/s。","因时间相等，速度的时间权重相同，所以等于(3＋7)/2；不是任何两速度都可这样算。"],"ans":"5m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"先以2m/s向右3s，再以6m/s向右1s，平均速度？","steps":["两段位移6m和6m，共12m。","总时间4s，平均速度12/4＝3m/s。","算术平均4m/s错误，因为时间权重3∶1。"],"ans":"3m/s向右。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]}],"practice":[{"q":"基础：位移24m、用时6s，平均速度？","steps":["按定义24/6＝4m/s。","方向沿位移，若题给正方向则写＋4。"],"ans":"4m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"理解：速度计某刻读数能表示整段平均速率吗？","steps":["速度计给该刻速率。","整段可能加减速，需总路程与总时间才能求平均。"],"ans":"不能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"应用：等距离两段速率10与20m/s，平均速率？","steps":["设各段L，则总时间L/10＋L/20＝3L/20。","平均2L/(3L/20)＝40/3≈13.3m/s。"],"ans":"约13.3m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]},{"q":"综合3.8：匀加速由2到8m/s用3s，位移和平均速度？","steps":["匀加速允许平均速度(2＋8)/2＝5m/s。","位移5×3＝15m；a＝2m/s²代s＝ut＋½at²得6＋9＝15m。"],"ans":"5m/s；15m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":["3.8"]}],"quick":["平均速度用位移；平均速率用路程","先求各段时间，避免错误平均"],"quiz":{"q":"检测：平均速度为0是否说明全程静止？","steps":["回到原点的运动也有总位移0。","例如走出再返回，路程非零；回读总位移定义。"],"ans":"不是，可能往返。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.6","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.6","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.7":{"goals":["按速度变化量求平均加速度","用v与a的方向判断速率增减"],"prerequisites":["3.2带符号速度","3.6平均量与瞬时量"],"flow":["初末速度矢量","Δv＝v−u","除时间","比较v和a方向"],"deep":["加速度量度速度改变的快慢而非物体走得快不快。高速匀速列车加速度为零，从静止发车时速度可接近零而加速度显著，二者不能互相替代。","一维中的负加速度只表示向负方向，速率是否减小还要看速度。v＜0且a＜0时，负方向速度的大小增大；v＞0、a＜0时才先减速。跨过v＝0后速率变化性质也会切换。","平均加速度Δv/Δt使用整个时间段，瞬时加速度对应v–t切线斜率。若速度方向变了，Δv必须按矢量差计算，而不是末速率减初速率。"],"derive":["a＝(v−u)/Δt，单位(m/s)/s＝m/s²；v–t直线斜率恒定表示a恒定。","一维v≠0时，v·a＞0速率增加，＜0速率减小；在转向瞬间v＝0，须看前后过程而非把乘积为0理解为永远不变。"],"exam":["先写u、v的正负号，再求差。","题问“加速还是减速”必须比较方向，不能只凭a符号。"],"examples":[{"q":"物体向右4m/s，经2s变为向左2m/s，求平均加速度。","steps":["取向右正，u＝＋4、v＝−2。","Δv＝−2−4＝−6m/s。","a＝−6/2＝−3m/s²，向左；不能按速率差(2−4)/2。"],"ans":"−3m/s²，向左。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]},{"q":"汽车速度从＋20m/s在5s内变为＋5m/s，平均加速度与速度变化大小？","steps":["Δv＝5−20＝−15m/s，变化大小15m/s。","平均a＝−15/5＝−3m/s²，方向负。","车速在此情境降低，但−3并非所有负加速度都减速的一般结论。"],"ans":"Δv大小15m/s；a＝−3m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]},{"q":"v＝−5m/s、恒a＝−2m/s²，1s后速率如何？","steps":["v末＝−5＋(−2)×1＝−7m/s。","速率由5增至7，说明加速且向负方向。","负加速度并非一定减速，关键是a与v同向。"],"ans":"速率增大到7m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]}],"practice":[{"q":"基础：2s内速度由3增至7m/s，加速度？","steps":["同一方向取正，Δv＝4m/s。","a＝4/2＝2m/s²。"],"ans":"2m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]},{"q":"理解：v＝0的瞬间，a必为0吗？","steps":["上抛最高点v＝0，但重力仍存在。","忽略阻力时a仍向下g，是反例。"],"ans":"不必。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]},{"q":"应用：v–t直线过(1,3)、(4,−3)，a多少？","steps":["斜率(−3−3)/(4−1)＝−6/3。","a＝−2m/s²，不是仅用末点−3/4。"],"ans":"−2m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]},{"q":"综合3.8：u＝6m/s、a＝−2m/s²，何时停瞬间并转向？","steps":["v＝u＋at＝6−2t。","v＝0得t＝3s；若该恒a持续，t＞3时v负，开始反向。"],"ans":"3s；持续加速度则之后反向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":["3.8"]}],"quick":["a看Δv/Δt；负号不代表减速","同向速率增，反向速率减"],"quiz":{"q":"检测：在0–2s速度先＋2变−2m/s，平均a为0吗？","steps":["末减初为−4m/s而非速率差0。","平均a＝−4/2＝−2m/s²；回读矢量差。"],"ans":"不是，是−2m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.7","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.7","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.8":{"goals":["从v–t图推导恒加速度公式","分段处理制动与反应时间"],"prerequisites":["3.5面积和斜率","3.7加速度恒定条件"],"flow":["恒a","v＝u＋at","有向梯形面积","位移公式","消元与条件检查"],"deep":["三条常用式并非彼此独立的记忆条目。a恒定使v随时间线性变化；把v–t梯形面积写成(u＋v)t/2，再代入v＝u＋at，才得到s＝ut＋½at²。","消去t得到v²＝u²＋2as，但开平方求v会丢方向信息，必须根据运动阶段选正负根。式中s是带方向位移，不是任意往返路程。","汽车刹停后通常保持静止，恒负a模型在停车时终止；把更长t直接代进去会把车算成反向运动。反应时间另为匀速段，停车距离＝反应距离＋制动距离。"],"derive":["s＝(u＋v)t/2＝ut＋½at²；又(v−u)(v＋u)＝at(u＋v)＝2as，得v²−u²＝2as，a＝0时也满足。","实验中测等时间位移s₁、s₂，差为aT²；若图线有明显弯曲或阻力变化，不能无检验地认为a恒定。"],"exam":["列u、v、a、s、t与正方向，再选不含多余未知量的公式。","停下、转向、碰撞、撤力是分段点，先检查所求时间是否跨段。"],"examples":[{"q":"汽车u＝20m/s、a＝−5m/s²，刹车后6s位移？停后不再运动。","steps":["停车时间0＝20−5t，t停＝4s。","恒a仅持续4s，位移s＝(0²−20²)/(2×−5)＝40m。","余2s静止，位移仍40m；代6s得30m相当于错误假定车倒行。"],"ans":"40m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]},{"q":"恒a运动u＝2m/s、a＝3m/s²持续4s，求v、s并验算。","steps":["v＝u＋at＝2＋3×4＝14m/s。","s＝ut＋½at²＝8＋24＝32m。","用平均速度(2＋14)/2＝8m/s乘4s也得32m；方向未反转，路程同为32m。"],"ans":"14m/s；32m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]},{"q":"u＝25m/s，反应0.60s，刹车a＝−6.0m/s²，80m处障碍，能停住吗？","steps":["反应段s₁＝25×0.60＝15m。","制动段s₂＝25²/(2×6)≈52.08m。","总停止距离67.08m＜80m，余12.92m。","两个阶段模型不同，不能把反应时间算进匀减速时长。"],"ans":"能，停下余约12.9m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]}],"practice":[{"q":"基础：从静止a＝2m/s²运动3s，v和s？","steps":["v＝0＋2×3＝6m/s。","s＝½×2×3²＝9m；平均速度3m/s乘3s也得9m。"],"ans":"6m/s；9m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]},{"q":"理解：匀变速运动中s一定等于路程吗？","steps":["若速度在区间内反向，位移存在抵消。","s是带符号净变化，路程要在v＝0处切开算绝对长度。"],"ans":"不一定，转向时通常不等。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]},{"q":"应用：u＝5m/s、a＝2m/s²、s＝24m，求v与t，运动同正方向。","steps":["v²＝25＋2×2×24＝121；本段向正方向取v＝11m/s。","t＝(11−5)/2＝3s；代s＝15＋9＝24m。"],"ans":"11m/s；3s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]},{"q":"综合3.3：u＝6m/s、a＝−2m/s²持续4s，位移和路程？","steps":["3s转向，前段位移9m。","末1s从静止向负方向位移−1m。","净位移8m、路程10m；恒a在此题明确持续，允许反向。"],"ans":"＋8m；10m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":["3.3"]}],"quick":["公式需恒a，s为位移","刹车先算停止时间；反应段另算"],"quiz":{"q":"检测：v²算得49，能不看运动方向就写v＝7吗？","steps":["平方式只给速率大小7。","速度可能＋7或−7，需看所求阶段与正方向；回读消元丢失符号。"],"ans":"不能，需确定正负方向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.8","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.8","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"3.9":{"goals":["将自由落体作为u＝0的恒加速度运动","处理上抛最高点、落地条件与测g图线"],"prerequisites":["3.8恒加速度公式","地面高度与相对位移的区别"],"flow":["仅重力且近地","a向下恒g","自由落体或上抛","边界与图线"],"deep":["本节自由落体专指从静止开始、仅受重力的下落；空气中羽毛与钢球不同步主要因阻力与质量的相对影响，不是重力加速度本身因质量而不同。近地高度较小可近似g恒定。","竖直上抛仍只受重力，但初速不为零，应使用一般匀加速度式。最高点速度瞬时为零，a仍向下；同一高度上下经过时速率相同的结论需无阻力与g恒定。","测g宜将h与t²作图：斜率g/2。手动反应计时、释放初速、空气阻力和高度零点都会影响结果；多次测量能降低随机波动，不能自动消除系统偏差。"],"derive":["向下为正、u＝0：h＝½gt²，v＝gt。向上为正上抛：y＝y₀＋ut−½gt²，v＝u−gt。","到最高点v＝0得t上＝u/g，代位移得H＝u²/(2g)；落回同高度时间2u/g，不适用于落到不同高度。"],"exam":["先画高度零点，落地用y＝0而不是机械设位移0。","实验题写控制释放条件、重复测量、作图轴单位与斜率意义；不声称某实验必考。"],"examples":[{"q":"石块由45m高静止落下，g＝10m/s²，求落地时间和速度。","steps":["向下正，45＝½×10×t²，t²＝9。","取未来时间t＝3.0s。","v＝gt＝30m/s向下；v²＝2gh＝900复核。"],"ans":"3.0s；30m/s向下。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]},{"q":"小球20m/s上抛，g＝10m/s²，在抛出后3s的位置与速度？","steps":["向上正，位移20×3−½×10×9＝15m。","速度20−10×3＝−10m/s，向下。","最高点发生在2s，3s时虽仍在出发点上方，却已下降，位置正号不等于速度向上。"],"ans":"上方15m；10m/s向下。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]},{"q":"气球向上10m/s时在75m处释放物体，g＝10，无阻力，求落地时间。","steps":["释放瞬间物体仍有初速度＋10m/s，并非静止。","取地面y＝0，0＝75＋10t−5t²，即t²−2t−15＝0。","t＝5或−3s，未来取5s；落地v＝10−50＝−40m/s。","最高点80m，落下速度√(2×10×80)＝40m/s，吻合。"],"ans":"5.0s；落地40m/s向下。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]}],"practice":[{"q":"基础：自由落体u是多少？","steps":["本节定义从静止释放。","所以u＝0，仅受重力；若有初速需一般竖直运动模型。"],"ans":"0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]},{"q":"理解：上抛最高点a为何不为0？","steps":["速度0只表示瞬时位置不再上升。","重力未消失，故a仍向下g；否则不能开始下落。"],"ans":"重力持续作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]},{"q":"应用：u＝20m/s上抛，g＝10，求上升高度和回原高度时间。","steps":["H＝u²/(2g)＝400/20＝20m。","t总＝2u/g＝4s；需无阻力且返回同高度。"],"ans":"20m；4s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]},{"q":"综合3.5：h–t²直线斜率4.90m/s²，测得g多少？","steps":["h＝(g/2)t²，斜率＝g/2。","g＝2×4.90＝9.80m/s²；轴横为s²、纵为m。"],"ans":"9.80m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":["3.5"]}],"quick":["自由落体u＝0；上抛不是u＝0","最高点v＝0而a＝g向下"],"quiz":{"q":"检测：物体落到比抛出点低的平台，还能用t＝2u/g吗？","steps":["2u/g推导用了回到同一高度。","不同平台需在y＝y₀＋ut−½gt²中代目标高度，回读落地边界。"],"ans":"不能直接用，需目标高度方程。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":3,"primary_section":"3.9","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":3,"section_id":"3.9","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys03","url":"https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]}},"物理4":{"4.1":{"goals":["由运动状态变化判断合外力而非单个力","画出同一对象的力并区分合力与速度"],"prerequisites":["3.7加速度与速度","矢量同向相加、反向相减"],"flow":["相互作用","同一物体受力","矢量合力","加速度","速度变化"],"deep":["力描述物体间相互作用，必须能说出施力者与受力者。推箱子匀速时推力存在但与阻力平衡，合力为零；这与“完全不受力”有相同的加速度，却是不同的受力情境。","合力决定加速度而非速度方向。向右滑行但合力向左，物体可先减速，速度并不会瞬间向左。撤去某个力后的运动需重新求所有剩余力。","受力图只画研究对象受到的外部作用，不画它施给别人的力，也不把ma当作另一个力。选系统后，系统内部相互作用不可重复算入外力。"],"derive":["同一直线取右正，ΣF＝F右−F左；a＝ΣF/m。1N＝1kg·m·s⁻²，量纲保证力与质量乘加速度匹配。","若物体做匀速直线运动，a＝0，故ΣF＝0；不能由此推出每个力分别为0。"],"exam":["写“合外力”而非仅“力”；描述力时加上受力对象。","根据速度图斜率求a，再反推合力，是连接第3章的解题路径。"],"examples":[{"q":"2kg箱子受10N向右拉力、10N向左阻力，向右匀速，合力和加速度？","steps":["取右正，合力10−10＝0N。","a＝0/2＝0；原有向右速度保持。","两力仍存在，合力为零不是没有受力。"],"ans":"0N；0m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"某物体原向左匀速，受力改变为向右合力。能否立刻说它向右运动？","steps":["合力向右说明加速度向右。","物体原速度仍向左，先减速；若作用足够久，可停下后转向右。","必须区分当前速度与变化趋势，仅凭合力不能确定当前速度。"],"ans":"不能，先可能向左减速。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"同一箱子拉力撤去后阻力维持4N向左，此时仍向右，运动如何？","steps":["合力−4N，a＝−4/2＝−2m/s²。","速度向右、加速度向左，因此先减速。","到停止后阻力模型可能改变，不能无条件继续按−2反向运动。"],"ans":"先向右减速，加速度2m/s²向左。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]}],"practice":[{"q":"基础：同向3N与5N作用同一物体，合力？","steps":["方向一致按矢量加法相加。","大小3＋5＝8N，沿共同方向。"],"ans":"8N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"理解：物体有向右速度，合力一定向右吗？","steps":["速度反映当前运动，合力决定变化。","制动时速度向右而合力向左，是反例。"],"ans":"不一定。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"应用：3kg物体受右12N左6N，a多少？","steps":["ΣF＝12−6＝6N。","a＝6/3＝2m/s²向右，质量单位为kg。"],"ans":"2m/s²向右。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"综合3.8：上题由静止持续2s，位移多少？","steps":["加速度恒2m/s²。","s＝½at²＝½×2×4＝4m向右；前提为力在2s内保持。"],"ans":"4m向右。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":["3.8"]}],"quick":["合力决定a，速度不必同向","ΣF＝0不等于每个力为0"],"quiz":{"q":"检测：受力图上写了mg、N和ma三个箭头，哪里需要改？","steps":["mg和N来自外部相互作用。","ma是合力的计算结果，不是新增相互作用，应从图中去掉并另列方程。"],"ans":"删去ma箭头。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.1","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.1","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.2":{"goals":["区分重力、支持力、弹簧力与静／动摩擦","依据接触与运动趋势作受力图"],"prerequisites":["4.1施力与受力对象","正交方向及形变量"],"flow":["找重力","逐个接触找弹力","判断相对滑动或趋势","选摩擦模型"],"deep":["支持力沿接触面法线，重力竖直向下，两者方向只有水平支承时才相反；N是否等于mg必须由垂直方向的运动方程求，不是定义。绳张力沿绳指向拉紧方向，理想轻绳与光滑滑轮才可近似各段等张力。","静摩擦在所需范围内自适应，满足","f_s","≤μ_sN。只有临界滑动时达到最大值；物体静止并不能直接说明f_s＝μ_sN。动摩擦f_k＝μ_kN是简化经验模型，现实可依速度、温度和材料变化。","弹簧F＝kx中的x是偏离自然长度的量，方向始终趋向恢复自然长度；伸长与压缩都要配方向，超过弹性限度模型可能失效。摩擦力抵抗接触面的相对滑动，不必与地面参考系中的物体速度反向。"],"derive":["水平桌面无竖直加速度且无其他竖直力时N−mg＝0；斜面无垂直加速度时N＝mgcosθ；外力斜拉会再次改变N。","对静止物体先由水平方程求所需f_s，再比较μ_sN；不足以维持才切换滑动模型。"],"exam":["先判断静或动摩擦，不能只因题目给μ就立即相乘。","在图上标出接触面、法线与相对运动方向，帮助检查摩擦箭头。"],"examples":[{"q":"2kg块放水平桌面，g＝10，μ_s＝0.4，受5N水平力仍静止，摩擦力多少？","steps":["N＝mg＝20N，最大静摩擦0.4×20＝8N。","平衡所需摩擦为5N，与外力反向，小于8N，静止可行。","实际摩擦5N而非8N。"],"ans":"5N，反向于外力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"2kg块在水平面受向右5N、向上竖直额外拉力6N，仍无竖直加速度，g＝10，求N和最大静摩擦；μ_s＝0.5。","steps":["竖直方程N＋6−20＝0，N＝14N。","最大静摩擦0.5×14＝7N，维持水平静止需5N，小于上限。","额外上拉使N减小，不能再用mg＝20N求摩擦上限。"],"ans":"N＝14N；f_s,max＝7N，静止时实际摩擦5N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"弹簧自然长0.20m，被拉至0.25m，k＝200N/m，求弹力大小。","steps":["形变量x＝0.25−0.20＝0.05m。","F＝kx＝200×0.05＝10N，方向指向恢复原长。","用总长0.25m会误算50N；需在弹性范围内。"],"ans":"10N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]}],"practice":[{"q":"基础：质量3kg、g＝10，重力多少？","steps":["W＝mg＝3×10＝30N。","方向竖直向下，单位N，不是kg。"],"ans":"30N向下。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"理解：传送带加速带动物体时摩擦可向前吗？","steps":["接触处物体相对带面有向后滑动趋势。","静摩擦对物体向前，提供前向加速度。"],"ans":"可以，抵抗相对趋势。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"应用：N＝50N、μ_k＝0.20、已滑动，摩擦大小？","steps":["使用给定库仑动摩擦模型f_k＝μ_kN。","0.20×50＝10N，方向反向于相对滑动。"],"ans":"10N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"综合4.7：2kg块N＝20N、μ_s＝0.4，施10N水平力能继续静止吗？","steps":["最大静摩擦8N，平衡需10N。","10＞8，静止条件失败，会开始滑动；之后加速度还需μ_k，不能自动用μ_s。"],"ans":"不能；后续计算需动摩擦系数。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":["4.7"]}],"quick":["静摩擦先求需求再查上限","弹簧用形变量；N由受力方程求"],"quiz":{"q":"检测：斜面上的支持力为什么不能直接取mg？","steps":["支持力沿法线，重力须分解。","无垂直加速度时N＝mgcosθ；回读方向条件。"],"ans":"因为重力仅法向分量由N平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.2","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":2,"question_no":6,"source":"https://duzhongacademy.com/pastpapers/uec-2025/physics/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.2","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.3":{"goals":["按矢量法则合成与正交分解力","说明分量并非额外新增作用力"],"prerequisites":["勾股定理与三角函数","4.1矢量合力"],"flow":["选轴与角","分力投影","逐轴代数和","合力大小和方向"],"deep":["两个力合成的平行四边形对角线从共同作用点指向对顶点。头尾相接的三角形法则给相同合向量；不能把两力大小直接相加，除非同方向。","正交分解是同一力在选定轴上的表达，不是额外新增两股力。受力图若既保留F又把Fx、Fy当独立力参与求和，会重复计数。","F与x正轴夹角θ时Fx＝Fcosθ、Fy＝Fsinθ；若角来自y轴需交换正弦余弦。斜面重力mg的沿面分量为mg sinθ，法向分量mg cosθ，检查θ→0时沿面分量应归零。"],"derive":["两力夹角θ时R²＝(F₁＋F₂cosθ)²＋(F₂sinθ)²＝F₁²＋F₂²＋2F₁F₂cosθ。","因−1≤cosθ≤1，得","F₁−F₂","≤R≤F₁＋F₂。合力方向用分量正负和tan值共同确定象限。"],"exam":["角的位置画在图上后再选sin／cos，最后用极端角检验。","含多个力时先对每轴求和再求模，不能先把各力模相加。"],"examples":[{"q":"6N向东、8N向北，求合力大小和方向。","steps":["R_x＝6、R_y＝8，R＝√(36＋64)＝10N。","相对东向夹角θ＝tan⁻¹(8/6)≈53.1°。","两分量都正，方向在东北象限。"],"ans":"10N，东偏北53.1°。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"5N力向东、另一5N力向西，合力多少；若改成同向呢？","steps":["反向分量相加＋5−5＝0N。","同向为＋5＋5＝10N。","两力大小相同并不能确定合力，方向或夹角是必要数据。"],"ans":"反向0N；同向10N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"2kg块在30°光滑斜面上，g＝10，求重力两分量。","steps":["mg＝20N。","沿斜面向下20sin30°＝10N，法向压向斜面20cos30°≈17.3N。","√(10²＋17.3²)≈20N，复原重力；分量不另算为第三第四个外力。"],"ans":"沿面10N；法向约17.3N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]}],"practice":[{"q":"基础：5N与12N垂直，合力？","steps":["正交使用勾股。","R＝√(25＋144)＝13N。"],"ans":"13N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"理解：F分为Fx、Fy后，计算可再加一次F吗？","steps":["Fx、Fy只是F的分量表示。","重复加F会把同一作用算两次，应选一种表达。"],"ans":"不能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"应用：大小10N力与x正轴60°，分量？","steps":["Fx＝10cos60°＝5N。","Fy＝10sin60°≈8.66N，角在第一象限故均正。"],"ans":"5N、8.66N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"综合4.1：8N与3N方向未知，合力范围？","steps":["最小反向","8−3","＝5N。","最大同向8＋3＝11N；夹角变化产生中间值。"],"ans":"5N至11N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":["4.1"]}],"quick":["先定轴和夹角，再投影","分量替代原力，不能重复相加"],"quiz":{"q":"检测：θ＝0的水平面上mg sinθ与mg cosθ分别多少？","steps":["sin0＝0，沿面重力为0。","cos0＝1，法向重力为mg；若相反，说明分解记反。"],"ans":"0与mg。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.3","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":2,"question_no":6,"source":"https://duzhongacademy.com/pastpapers/uec-2025/physics/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.3","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.4":{"goals":["用牛顿第一定律描述合外力为零的运动","理解理想实验与惯性参照系的作用"],"prerequisites":["3.4速度恒定","4.1合力为零与无受力的区别"],"flow":["减少阻力的证据","理想无阻情境","速度不变","第一定律与惯性系"],"deep":["日常物体推后会停，不能由此得出“运动需要持续推力”。停止过程本身说明速度正在改变，常由摩擦和阻力产生合力。减少阻力后滑行更久，支持把无阻极限理解为速度保持。","第一定律同时规定一个特殊的参照系类别：自由物体在其中保持匀速直线运动。加速车内看无水平力小球可能相对车向后加速，不能把这个观察不加说明地套成地面中的力学结论。","合外力为零时，既可静止又可非零恒速度，具体由初始状态决定。第一定律不是“所有物体最后会停下”，也不能由ΣF＝0单独确定某个速度数值。"],"derive":["若ΣF＝0，则速度变化为零，v(t)＝v₀；但v₀由先前运动条件给出。","理想实验是受实测趋势约束的推理，不是已经在现实中完全去除所有作用后的直接观察。"],"exam":["判断题要同时写“静止或匀速直线”，并加合外力与惯性系条件。","“撤去推力”不代表“合外力立即为零”，需查摩擦是否仍在。"],"examples":[{"q":"冰面上块原向东3m/s，忽略一切水平阻力，撤去拉力后怎样运动？","steps":["撤力后水平合力0。","初速度仍向东3m/s，第一定律给速度保持。","不会因为没有向前拉力而自行减速。"],"ans":"向东3m/s匀速。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"原本静止与原本以2m/s运动的两物体，在水平合力都为0时，3s后水平位移各多少？","steps":["第一物体初速0，保持静止，位移0。","第二物体初速2m/s，保持匀速，位移2×3＝6m。","同为零合力不意味着相同速度，初态不同。"],"ans":"0m、6m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"车厢突然向前加速，地面看来小球水平无力，车内看来球向后，这否定第一定律吗？","steps":["地面近似惯性系，小球水平速度近似保持。","车厢速度增加，相对车的小球落后。","车厢是加速参照系，不能直接用惯性系定律解释相对加速度为外力造成。"],"ans":"不否定，两个参照系性质不同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]}],"practice":[{"q":"基础：合外力为零的物体可能静止吗？","steps":["若初速度0，速度保持0。","若初速度非0，则保持该恒速度。"],"ans":"可以，但也可匀速运动。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"理解：桌面书静止是否证明无力？","steps":["重力和支持力都存在。","两者合力为零，书静止不能证明单个力消失。"],"ans":"不是，受平衡力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"应用：无水平合力物体以4m/s运动5s，位移？","steps":["速度保持4m/s。","s＝vt＝4×5＝20m，沿原方向。"],"ans":"20m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"综合3.7：v–t图水平非零时a和合力？","steps":["图斜率为0，a＝0。","恒质量、惯性系下ΣF＝ma＝0，速度本身不必0。"],"ans":"a＝0、合力0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":["3.7"]}],"quick":["无合力保持原速度，不指定速度必须为0","撤去一个力后重新查合力"],"quiz":{"q":"检测：真实滑块会停就能推翻理想无摩擦结论吗？","steps":["真实滑块有阻力，条件不同。","应检验减少阻力后趋势是否符合模型，回读理想实验与条件。"],"ans":"不能，须比较相同条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.4","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.4","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.5":{"goals":["用质量量度惯性并与重量区分","按受力和原运动状态解释惯性现象"],"prerequisites":["4.4第一定律","kg与N的单位区别"],"flow":["原运动状态","外力改变部分运动","其余部分保持趋势","质量量度抗变化"],"deep":["惯性是物体保持原运动状态的性质，不是一个施力者。说“乘客受到惯性向前推”无法指出外部相互作用，容易把运动趋势误画为力；应描述身体原来向前运动、受约束后才改变。","在同一外力下，质量大则加速度小，表示运动状态更难改变。速度影响动量和动能，但不改变经典惯性质量；高速小球仍可比静止大车质量小、惯性小。","质量单位kg，重量是重力mg、单位N。把相同物体带到月球，经典质量不变而重量随g变小；不能因为“变轻”就说更容易获得同一水平力下的加速度。"],"derive":["对相同F，a₁/a₂＝m₂/m₁；两量同条件比较才反映惯性差异。","用m＝F/a可测惯性质量；用W/g可求相同单位下的质量，二者是不同测量路径。"],"exam":["解释惯性现象按“原运动—谁受力改变—谁暂保持—出现何现象”展开。","避免“有运动才有惯性”“惯性被用完”等说法。"],"examples":[{"q":"同一10N力分别作用2kg与5kg物体，求a并比较惯性。","steps":["a小＝10/2＝5m/s²，a大＝10/5＝2m/s²。","5kg物体速度更难改变，惯性更大。","结论与它们最初是否静止无关。"],"ans":"5与2m/s²；5kg惯性较大。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]},{"q":"同一物体在两地重量分别100N、20N，当地g分别10、2m/s²，质量和惯性是否变化？","steps":["两地质量分别W/g＝100/10＝10kg、20/2＝10kg。","重量变化由g引起，质量未变。","经典惯性由质量量度，所以不因变轻而减为五分之一。"],"ans":"均10kg，惯性不变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]},{"q":"60kg人到g＝1.6m/s²的月面，质量、重量分别多少？","steps":["经典质量仍为60kg。","重量W＝60×1.6＝96N，地球若g＝10则为600N。","质量与重量不同，不能把96N写为96kg。"],"ans":"60kg；96N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]}],"practice":[{"q":"基础：静止物体有没有惯性？","steps":["惯性是一切有质量物体的性质。","静止时体现为保持静止的趋势。"],"ans":"有。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]},{"q":"理解：同一小车快一些，惯性是否变大？","steps":["本章经典模型中惯性由质量决定。","速度变大增加动量和动能，不使质量改变。"],"ans":"不变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]},{"q":"应用：4kg物体在8N合力下，a多少？","steps":["a＝F/m＝8/4＝2m/s²。","若同力作用8kg，a减为1，符合惯性比较。"],"ans":"2m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]},{"q":"综合4.4：急刹车乘客前倾，用惯性解释并指出安全带作用。","steps":["刹车前车与人都向前运动；车受阻力减速。","人的躯干原有向前速度，若未受足够约束会相对车前移。","安全带施力使躯干减速，不是消灭惯性。"],"ans":"原速度保持趋势；安全带提供减速作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":["4.4"]}],"quick":["惯性是性质不是力；质量量度惯性","质量kg，重量mg单位N"],"quiz":{"q":"检测：“安全带抵消惯性”应如何改写？","steps":["惯性不是可与力相抵的向量。","安全带提供外力，改变乘客速度；回读施力者和受力者。"],"ans":"改为安全带施力使人减速。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.5","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.5","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.6":{"goals":["按方向计算动量与动量变化","区分动量与动能并限定动量变化率适用系统"],"prerequisites":["3.2矢量速度","质量固定的经典模型"],"flow":["p＝mv","末减初求Δp","平均合力Δp/Δt","系统边界与动量通量"],"deep":["动量保留速度方向，反弹时即使速率相同也有非零动量变化。先选正方向，分别算p初、p末再相减，不能用两速率之差替代。","对质量恒定的一个物体，Δp＝mΔv，因此平均合外力为Δp/Δt。瞬时形式ΣF＝dp/dt针对确定的封闭物质系统；火箭自身质量随喷气流出而变，作为开放系统必须计动量通量，不能直接套ΣF＝d(mv)/dt来求火箭加速度。","动能½mv²是非负标量；两物体动量可相消，但动能不能因方向相反而抵消。同样动量大小下，质量越大动能p²/(2m)越小。"],"derive":["固定m时p²＝m²v²，除以2m得E_k＝p²/(2m)。单位(kg·m/s)²/kg＝kg·m²/s²＝J。","动量变化率单位kg·m/s²＝N；有限时间得到平均合力，不保证瞬时力恒定。"],"exam":["反弹题建议列初末两行符号。","所求为冲量或力时再除接触时间，不把Δp和p混写。"],"examples":[{"q":"0.50kg球以6m/s向右撞墙，以4m/s向左弹回，求Δp。","steps":["取右正，p初＝0.50×6＝＋3kg·m/s。","p末＝0.50×(−4)＝−2kg·m/s。","Δp＝−2−3＝−5kg·m/s，方向向左，大小5。"],"ans":"−5kg·m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]},{"q":"两个物体动量大小都6kg·m/s，质量分别2kg、3kg，动能各多少？","steps":["E_k＝p²/(2m)。","2kg物体为36/4＝9J，3kg物体为36/6＝6J。","同动量不等于同动能，且结果为标量不带运动方向。"],"ans":"9J、6J。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]},{"q":"上题接触0.020s，球的平均合力？","steps":["平均合力＝Δp/Δt＝−5/0.020＝−250N。","方向向左；这是球受的合力平均值。","若要求仅墙力还需说明其他方向力或忽略其影响。"],"ans":"250N向左。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]}],"practice":[{"q":"基础：2kg物体以3m/s向东，动量？","steps":["p＝mv＝2×3＝6kg·m/s。","方向与速度相同，为向东。"],"ans":"6kg·m/s向东。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]},{"q":"理解：等质量球以相同速率反向运动，总动量为0，总动能也为0吗？","steps":["两个矢量动量相反相消。","动能各为½mv²，都是正值，总和mv²，不是0。"],"ans":"总动量0；总动能不为0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]},{"q":"应用：1kg球从＋4变−4m/s，Δp多少？","steps":["p末−p初＝1×(−4)−1×4。","得到−8kg·m/s，不能答0。"],"ans":"−8kg·m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]},{"q":"综合3.7：恒质量3kg、a＝2m/s²持续4s，Δp与平均力？","steps":["Δv＝at＝8m/s。","Δp＝mΔv＝24kg·m/s；平均力24/4＝6N，也等于ma。"],"ans":"24kg·m/s；6N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":["3.7"]}],"quick":["Δp＝p末−p初，先带方向","变质量开放系统必须处理动量通量"],"quiz":{"q":"检测：球反弹前后速率相同，动量变化能为0吗？","steps":["速度方向反转使末动量为初动量负值。","Δp＝−2p初，非零；若答0需回读矢量差。"],"ans":"不能，反向导致动量改变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.6","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.6","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.7":{"goals":["用受力图建立逐轴ΣF＝ma","解连接体、电梯和斜面模型并核验假设"],"prerequisites":["4.2摩擦与支持力","4.3正交分解；3.8恒a运动学"],"flow":["选对象和系统","受力图","逐轴方程","求a和内力","运动学与接触检查"],"deep":["ΣF、m、a必须对应同一个对象或整体，不能把A的力、A＋B的质量和B的加速度混在一式中。连接物体只有在轻绳绷紧、不可伸长等约束成立时才具有相关加速度。","整体法相加消去内部相互作用，适合求共同加速度；绳张力或接触力属于内力，需再隔离某个物体求出。求得张力若为负，表示绳不能提供所假定的推力，模型要重建。","电梯秤测支持力N，不直接测mg。向上选正时N−mg＝ma；上行减速a向下，读数小于mg，不能按“向上运动”判断超重。斜面则先用法向无加速度求N，再按相对滑动方向求摩擦。"],"derive":["两块在光滑水平面轻绳相连，F拉前块：整体F＝(m₁＋m₂)a；后块T＝m₁a，得T＝m₁F/(m₁＋m₂)。","实验检验F与a关系要保持总质量不变；若用悬挂重物mg近似绳张力，要满足相应近似并评估滑轮、摩擦和钩码质量的影响。"],"exam":["先写受力方程再代公式，尤其注意哪个方向的a为0。","图线截距反映未计入作用或测量偏差，不应仅凭一条拟合线就声称定律失效。"],"examples":[{"q":"水平光滑面上2kg、3kg两块轻绳相连，10N拉3kg前块，求a、T。","steps":["整体F＝(2＋3)a，a＝10/5＝2m/s²。","隔离后面2kg块，唯一水平力T＝2×2＝4N。","前块验算10−4＝3×2＝6N，满足方程。"],"ans":"a＝2m/s²；T＝4N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]},{"q":"质量4kg物块在水平面受20N水平拉力，动摩擦系数0.25，g＝10，已滑动，求a。","steps":["竖直无加速度，N＝40N，动摩擦f＝0.25×40＝10N。","水平ΣF＝20−10＝10N，a＝10/4＝2.5m/s²。","使用动摩擦因物块明确滑动；不能把拉力20N直接除以质量而漏阻力。"],"ans":"2.5m/s²沿拉力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]},{"q":"60kg人随电梯向上运动但以2m/s²减速，g＝10，秤示支持力？","steps":["取上正，a＝−2m/s²。","N−600＝60×(−2)，得N＝480N。","N＜mg为失重，速度向上不代表超重；若秤以kg标示按其校准折算。"],"ans":"480N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]}],"practice":[{"q":"基础：2kg受6N合力，a？","steps":["a＝ΣF/m＝6/2。","3m/s²，方向与合力一致。"],"ans":"3m/s²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]},{"q":"理解：为什么求连接体张力通常要隔离？","steps":["整体方程内部两张力相消。","整体只给共同a，要恢复内力必须选一个组成物体列式。"],"ans":"整体方程消去了内力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]},{"q":"应用：2kg在30°光滑斜面下滑，g＝10，求a。","steps":["法向N＝mgcos30°。","沿面合力mgsin30°＝ma，a＝10×0.5＝5m/s²，向下。"],"ans":"5m/s²沿面向下。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]},{"q":"综合3.8：上题由静止滑2s，位移与速度？","steps":["恒a＝5m/s²。","s＝½×5×4＝10m；v＝5×2＝10m/s。","需斜面有足够长度且忽略阻力。"],"ans":"10m；10m/s。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":["3.8"]}],"quick":["同一个对象的F、m、a","整体求a，隔离求内力；超重看a方向"],"quiz":{"q":"检测：计算出支持力N＝−5N时，能保留负支持力吗？","steps":["普通无粘附接触不能拉住物体。","负N表示已失去接触或方向假设不成立，需重新建模；回读接触条件。"],"ans":"不能，应检查并重建接触模型。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.7","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[{"year":2025,"paper_no":2,"question_no":6,"source":"https://duzhongacademy.com/pastpapers/uec-2025/physics/p1/attempt","source_type":"third_party_reference","verification_status":"partially_verified","notes":"已核对平台题干及年份卷别标签；未与官方原卷或评分表核对，不计官方考频。"}],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.7","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]},"4.8":{"goals":["识别一对作用与反作用的两个受力对象","区分第三定律配对和平衡力"],"prerequisites":["4.1施力与受力对象","4.7系统与内部力"],"flow":["明确A作用B","寻找B作用A","不同受力对象","分别列运动方程"],"deep":["第三定律配对是“A对B”与“B对A”的同一相互作用的两端，两力同时存在、等大反向。无论两物体是否静止、质量是否相同，配对力都相等；加速度可因质量不同而不同。","平衡力则作用于同一个对象、合力为零。书的重力与桌对书的支持力是平衡力，重力的反作用是书对地球的引力，而非桌的支持力。","分析一个物体时不能把它施出的反作用力也放进受力图来“抵消”；分析包含两物体的整体时，这对内力才在总外力计算中相消。步行、推进都需找系统与外部介质的作用，不能只比两股内部拉力。"],"derive":["同一次相互作用F_A→B＝−F_B→A；各物体运动仍满足ΣF_B＝m_Ba_B、ΣF_A＝m_Aa_A。","若只有这对相互作用，","a_A","/","a_B","＝m_B/m_A；等大力不意味着等大加速度。"],"exam":["给每个力写“谁对谁”，交换名字即可找反作用。","马车问题隔离车分析拉力与车阻力；不要拿车拉马的力和马拉车的力比较谁更大。"],"examples":[{"q":"书静止桌上，找桌对书支持力N的反作用，并说明与书重力关系。","steps":["N为桌对书，反作用须交换为书对桌压力，受力者是桌。","书重力是地球对书，和N共同作用书上且平衡。","重力与N不是第三定律配对，因为施受双方不同。"],"ans":"反作用为书对桌压力；N与书重力为平衡力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]},{"q":"人以向后摩擦力作用地面，地面对人的反作用方向是什么？与人的重力可配对吗？","steps":["交换施受者：地面对人摩擦向前。","人受重力来自地球引力，其反作用是人对地球引力。","摩擦配对与重力配对属于不同相互作用，不能混成一对。"],"ans":"地面对人摩擦向前；不与重力配对。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]},{"q":"50kg与100kg两人在光滑冰面互推，作用大小100N，各自a？","steps":["互推力等大反向，为100N。","50kg人a＝100/50＝2m/s²，100kg人a＝100/100＝1m/s²。","方向相反，加速度不同由质量不同决定，不是第三定律不成立。"],"ans":"2与1m/s²，方向相反。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]}],"practice":[{"q":"基础：人推墙20N，墙对人多少？","steps":["同一相互作用两端等大反向。","墙对人20N，方向与人推墙相反。"],"ans":"20N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]},{"q":"理解：这两个20N能在人的受力图上相消吗？","steps":["人推墙作用于墙，不属于人受的力。","人的受力图只含墙对人及其他外力，不能把两者都画进去。"],"ans":"不能，受力者不同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]},{"q":"应用：马拉车300N、车阻力100N、车质量200kg，求车a。","steps":["隔离车：前拉300、后阻100。","合力200N，a＝200/200＝1m/s²向前；车拉马300N不作用于车。"],"ans":"1m/s²向前。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]},{"q":"综合4.7：上题车拉马的反作用多大？为何车仍可加速？","steps":["车拉马仍为300N反向。","它作用在马而非车；车所受合力为300−100＝200N。","等大内力不妨碍各自受非零合外力。"],"ans":"300N；车有向前200N合力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":["4.7"]}],"quick":["反作用配对交换施受者","平衡力同物体，第三定律配对不同物体"],"quiz":{"q":"检测：“大车撞小车，大车施力更大”正确吗？","steps":["接触相互作用力始终等大反向。","小车可能因质量较小、结构不同而加速度或损伤更大；回读力与响应的区别。"],"ans":"不正确，两接触力等大。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":4,"primary_section":"4.8","related_sections":[]},"verification_status":"partially_verified","exam_evidence":[],"subject":"物理","subject_code":"physics","chapter_id":4,"section_id":"4.8","content_sources":[{"source_id":"dz_physics","page":2,"version":"2026","access_date":"2026-11-17"},{"source_id":"school","page":3,"version":"12/11/2026","access_date":"2026-11-17"},{"source_id":"science_phys04","url":"https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system","page_or_section":"来源台账逐节条目","version":"OpenStax","access_date":"2026-11-17"}]}}};
